// SPDX-License-Identifier: LGPL-3.0-or-later
// Part of akantu-rs, a Rust port of Akantu (EPFL/LSMS). Differential tests
// of the cohesive model against fixtures/model/cohesive/* (generated by
// oracle/probes/cohesive/cohesive_probe.cc from the upstream
// TestSMMCFixture scenarios). Exact rule: every recorded quantity is
// compared bitwise (operation order replicated), including
// `facet_material`, the blocked flags, the implicit `K` and internals and the
// buildfragments internals and fragment element lists; `assert_all_compared`
// fails on a recorded quantity that is neither compared nor explicitly
// skipped (only `K/*` of the default-mode implicit run, whose `K` is
// promoted to unsymmetric storage, UD-034).
//
// Upstream-defect switches (`CohesiveUpstreamCompat`) are set
// only where a case depends on them: 3-D extrinsic cases compare upstream's
// `init/tangents` (UD-217), random-strength cases pair facets and strengths
// as upstream (UD-040), implicit compat replays use upstream's tangent `σc`
// (UD-220), `δ_max` without history (UD-028) and per iterate (UD-241),
// upper-triangle `K` (UD-034) and accept the intrinsic `cohesive_linear`
// (UD-224, refused by default); the corrected defaults are checked in
// `review_v48_regressions.rs`, `review_v52_regressions.rs` and
// `independent_checks.rs`.
//
// `COH_FIXTURE_ROOT=<dir>` reads staged (unpromoted) cases from `<dir>`
// instead of `fixtures/` (probe development; checksums not verified).

mod common;

use akantu_validation::reduce::NanMinMax;
use std::path::PathBuf;

use akantu_cohesive::SolidMechanicsModelCohesive;
use akantu_core::enums::AnalysisMethod;
use akantu_core::{ElementType, GhostType, Real};
use akantu_model::ModelOptions;
use akantu_parser::Parser;
use akantu_validation::{Fixture, fixtures_root};
use common::{FlagOnly, StrainIncrement};

fn root() -> (PathBuf, bool) {
    match std::env::var("COH_FIXTURE_ROOT") {
        Ok(d) if !d.is_empty() => (PathBuf::from(d), true),
        _ => (fixtures_root(), false),
    }
}

fn open(case: &str) -> Option<Fixture> {
    let (r, staged) = root();
    let dir = r.join("model/cohesive").join(case);
    if !dir.join("manifest.json").exists() {
        return None;
    }
    let f = Fixture::open(&dir).unwrap_or_else(|e| panic!("{case}: {e}"));
    if !staged {
        f.require_golden().unwrap();
        f.verify_checksums().unwrap();
    }
    Some(f)
}

fn cases() -> Vec<String> {
    let (r, _) = root();
    let mut v: Vec<String> = std::fs::read_dir(r.join("model/cohesive"))
        .map(|rd| {
            rd.filter_map(|e| e.ok())
                .filter(|e| e.path().join("manifest.json").exists())
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    v.sort();
    v
}

fn f64s(f: &Fixture, name: &str) -> Vec<f64> {
    f.load_f64(name)
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
        .data
}

fn i64s(f: &Fixture, name: &str) -> Vec<i64> {
    f.load_i64(name)
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
        .data
}

fn has(f: &Fixture, name: &str) -> bool {
    f.quantity(name).is_ok()
}

fn bools(a: &[bool]) -> Vec<i64> {
    a.iter().map(|&b| i64::from(b)).collect()
}

/// Every recorded quantity of `f` must have been compared by the replay
/// (names in `compared`) or match a pattern of `skip` (given at the call
/// site with its reason).
fn assert_all_compared(f: &Fixture, compared: &[String], skip: &[&str]) {
    let mut missing = Vec::new();
    for q in &f.manifest().quantities {
        let n = q.name.as_str();
        if compared.iter().any(|c| c == n)
            || skip
                .iter()
                .any(|p| akantu_validation::tolerance::glob_match(p, n))
        {
            continue;
        }
        missing.push(n.to_owned());
    }
    assert!(
        missing.is_empty(),
        "{}: recorded but not compared: {missing:?}",
        f.case_id()
    );
}

fn param<'a>(f: &'a Fixture, key: &str) -> &'a serde_json::Value {
    &f.manifest().parameters[key]
}

// ---------------------------------------------------------------------------
// Replay guard: every replay test
// iterates over the **expected** cases of its family (the probe's case list,
// `oracle/probes/cohesive/cohesive_probe.cc` `main`), not over the cases it
// happens to find. A missing fixture tree, a missing, renamed or extra case,
// a case that records an upstream error it did not record before (or the
// reverse) and a case that compares fewer (or more) values all fail. The
// value totals are the counts of the release tier (the unoptimised fast
// tier skips the 3-D cases, whose totals are listed
// separately). `COH_CASES=<id>,…` (probe development) restricts a test to
// the listed cases: each must be an expected case of the family and
// present; the totals are then not asserted.
// ---------------------------------------------------------------------------

/// The upstream TestSMMCFixture meshes of the probe (`types`).
const FIXTURE_TYPES: [&str; 9] = [
    "segment_2",
    "triangle_3",
    "quadrangle_4",
    "triangle_3_quadrangle_4",
    "triangle_6",
    "quadrangle_8",
    "triangle_6_quadrangle_8",
    "tetrahedron_4",
    "tetrahedron_10",
];

/// Cases of `fixture_cases_bitwise` (probe order): 36 TestSMMCFixture, 1
/// random-strength, 16 law (4 record an upstream error), 8 finite-deformation.
fn expected_fixture_family() -> Vec<String> {
    let mut v = Vec::new();
    for t in FIXTURE_TYPES {
        for ext in ["extrinsic", "intrinsic"] {
            for mode in ["i", "ii"] {
                v.push(format!("fixture_{ext}_mode_{mode}_{t}"));
            }
        }
    }
    v.push("random_extrinsic_mode_i_triangle_3".to_owned());
    for law in [
        "linear_fatigue",
        "linear_friction",
        "linear_uncoupled",
        "linear_kappa",
    ] {
        for mode in ["i", "ii"] {
            for t in ["triangle_3", "tetrahedron_4"] {
                v.push(format!("law_{law}_mode_{mode}_{t}"));
            }
        }
    }
    for t in &FIXTURE_TYPES[1..] {
        v.push(format!("fixture_extrinsic_mode_i_finite_def_{t}"));
    }
    v
}

/// Value totals of `fixture_cases_bitwise`: every case replayed (release
/// tier, `COH_ALL=1`) and with the 3-D cases skipped (unoptimised build).
const FIXTURE_FAMILY_VALUES: usize = 1_421_424;
const FIXTURE_FAMILY_VALUES_WITHOUT_3D: usize = 532_500;

/// `implicit_cases`: two compat replays (2 × 2,129 values) and the
