/// `cmf_oracle_cases`: the 3-D prescribed-motion
/// friction case and the implicit friction case.
const CMF_FAMILY: [&str; 2] = [
    "cmf_friction_prescribed_tetrahedron_4",
    "cmf_implicit_friction_prestressed_sliding",
];

/// Every expected case of every replay family (the union must equal the
/// fixture tree, see `every_fixture_case_belongs_to_a_replay_family`).
fn all_expected_cases() -> Vec<String> {
    let mut v = expected_fixture_family();
    v.extend(IMPLICIT_FAMILY.iter().map(|s| (*s).to_owned()));
    v.extend(ADV_EXPLICIT_FAMILY.iter().map(|s| (*s).to_owned()));
    v.extend(ADV_IMPLICIT_FAMILY.iter().map(|s| (*s).to_owned()));
    v.extend(V57_FAMILY.iter().map(|s| (*s).to_owned()));
    v.extend(VA3_FAMILY.iter().map(|s| (*s).to_owned()));
    v.extend(V92_FAMILY.iter().map(|s| (*s).to_owned()));
    v.extend(CMF_FAMILY.iter().map(|s| (*s).to_owned()));
    v.push("buildfragments".to_owned());
    v.sort();
    v
}

/// `COH_CASES` (probe development): the explicitly requested cases.
fn requested_cases() -> Option<Vec<String>> {
    match std::env::var("COH_CASES") {
        Ok(s) if !s.is_empty() => Some(s.split(',').map(str::to_owned).collect()),
        _ => None,
    }
}

/// The cases a family test replays: the expected list (sorted), or the
/// `COH_CASES` subset of it. Every one of them must be present in the
/// fixture tree (a missing tree or case fails here).
fn family_cases(family: &str, expected: &[String]) -> Vec<String> {
    let mut expected: Vec<String> = expected.to_vec();
    expected.sort();
    let wanted = match requested_cases() {
        Some(req) => expected
            .into_iter()
            .filter(|c| req.contains(c))
            .collect::<Vec<_>>(),
        None => expected,
    };
    let present = cases();
    let missing: Vec<&String> = wanted.iter().filter(|c| !present.contains(c)).collect();
    assert!(
        missing.is_empty(),
        "{family}: expected oracle case(s) missing from {}: {missing:?}",
        root().0.join("model/cohesive").display()
    );
    wanted
}

/// The upstream-error marker of a case must be recorded exactly for the
/// cases of [`UPSTREAM_ERROR_CASES`].
fn assert_upstream_error_status(case: &str, f: &Fixture) {
    let recorded = !param(f, "upstream_error").is_null();
    let expected = UPSTREAM_ERROR_CASES.contains(&case);
    assert_eq!(
        recorded, expected,
        "{case}: upstream_error recorded = {recorded}, expected {expected}"
    );
}

/// The value total of a family run: `full` when every case was replayed,
/// `partial` when the unoptimised build skipped the 3-D cases; not asserted
/// for a `COH_CASES` subset.
fn assert_family_total(family: &str, total: usize, full: usize, partial: usize, skipped: usize) {
    if requested_cases().is_some() {
        eprintln!("{family}: COH_CASES subset: {total} values compared (total not asserted)");
        return;
    }
    let expected = if skipped == 0 { full } else { partial };
    assert_eq!(
        total, expected,
        "{family}: values compared ({skipped} case(s) skipped in this build)"
    );
}

/// Unoptimised builds skip the 3-D replays unless `COH_ALL` is set (or the
/// cases were requested explicitly).
fn skip_3d() -> bool {
    cfg!(debug_assertions) && std::env::var("COH_ALL").is_err() && requested_cases().is_none()
}

#[test]
fn every_fixture_case_belongs_to_a_replay_family() {
    let present = cases();
    let expected = all_expected_cases();
    if let Some(req) = requested_cases() {
        // a COH_CASES subset: each requested case is an expected, present case
        let bad: Vec<&String> = req
            .iter()
            .filter(|c| !expected.contains(c) || !present.contains(c))
            .collect();
        assert!(
            bad.is_empty(),
            "COH_CASES: unknown or missing cases {bad:?}"
        );
        return;
    }
    let unclaimed: Vec<&String> = present.iter().filter(|c| !expected.contains(c)).collect();
    let missing: Vec<&String> = expected.iter().filter(|c| !present.contains(c)).collect();
    assert!(
        unclaimed.is_empty() && missing.is_empty(),
        "fixtures/model/cohesive: cases without a replay family {unclaimed:?}, expected cases missing {missing:?}"
    );
    assert_eq!(present.len(), 81, "number of cohesive oracle cases");
}

/// Collected mismatches of one case.
#[derive(Default)]
struct Report {
    compared: usize,
    errors: Vec<String>,
    /// Names of the quantities compared.
    names: Vec<String>,
}

impl Report {
    fn bits(&mut self, what: &str, ours: &[f64], theirs: &[f64]) {
        self.names.push(what.to_owned());
        if ours.len() != theirs.len() {
            self.errors.push(format!(
                "{what}: length {} vs oracle {}",
                ours.len(),
                theirs.len()
            ));
            return;
        }
        self.compared += ours.len();
        let mut n = 0;
        let mut first = None;
        let mut maxrel: f64 = 0.0;
        for (i, (a, b)) in ours.iter().zip(theirs).enumerate() {
            // D-046: bit identity, or default NaNs of either sign
            if !akantu_validation::exact_eq(*b, *a) {
                n += 1;
                first.get_or_insert(i);
                let rel = (a - b).abs() / b.abs().max(1e-300);
                maxrel = maxrel.nan_max(rel);
            }
        }
        if let Some(i) = first {
            self.errors.push(format!(
                "{what}: {n}/{} differ (first #{i}: {:e} vs {:e}, max rel {maxrel:e})",
                ours.len(),
                ours[i],
                theirs[i]
            ));
        }
    }

    fn ints(&mut self, what: &str, ours: &[i64], theirs: &[i64]) {
        self.names.push(what.to_owned());
        self.compared += ours.len();
        if ours != theirs {
            let first = ours.iter().zip(theirs).position(|(a, b)| a != b);
            let ctx = first.map(|i| {
                let lo = i.saturating_sub(2);
                let hi = (i + 6).min(ours.len()).min(theirs.len());
                format!("ours {:?} oracle {:?}", &ours[lo..hi], &theirs[lo..hi])
            });
            self.errors.push(format!(
                "{what}: differ (len {} vs {}, first index {first:?}: {})",
                ours.len(),
                theirs.len(),
                ctx.unwrap_or_default()
            ));
        }
    }
}

fn digest(arrays: &[&[f64]]) -> String {
    let mut bytes = Vec::new();
    for a in arrays {
        for v in *a {
            // D-046 (3): default NaNs canonicalised (no recorded digest changes)
            bytes.extend_from_slice(&akantu_validation::canonical_le_bytes(*v));
        }
    }
    akantu_validation::checksum::sha256_bytes(&bytes)
}

/// Every recorded internal `material/<name>/<internal>/<type>` and element
/// filter of the cohesive material `name`.
fn compare_internals(
    f: &Fixture,
    mat: &akantu_cohesive::MaterialCohesive,
    name: &str,
    r: &mut Report,
) {
    let prefix = format!("material/{name}/");
    for key in f.quantity_names(&format!("{prefix}*")) {
        let rest = &key[prefix.len()..];
        let Some((internal, tn)) = rest.split_once('/') else {
            r.errors.push(format!("{key}: unexpected name"));
            continue;
        };
        let ty = cohesive_type(tn);
        if internal == "filter" {
            let filter: Vec<i64> = akantu_solid::Material::base(mat)
                .element_filter
                .get(ty, GhostType::NotGhost)
                .map(|a| a.as_slice().iter().map(|&x| i64::from(x)).collect())
                .unwrap_or_default();
            r.ints(key, &filter, &i64s(f, key));
            continue;
        }
        let internal = if internal == "delta_max" {
            "delta max"
        } else {
            internal
        };
        let ours = mat
            .array(internal, ty, GhostType::NotGhost)
            .map(|a| a.as_slice().to_vec())
            .unwrap_or_default();
        r.bits(key, &ours, &f64s(f, key));
    }
}

/// `facet_material/<type>` (final state).
fn compare_facet_material(f: &Fixture, model: &SolidMechanicsModelCohesive, r: &mut Report) {
    for key in f.quantity_names("facet_material/*") {
        let ty = cohesive_type(&key["facet_material/".len()..]);
        let ours: Vec<i64> = model
            .ext
            .facet_material
            .get(ty, GhostType::NotGhost)
            .map(|a| a.as_slice().iter().map(|&x| i64::from(x)).collect())
            .unwrap_or_default();
        r.ints(key, &ours, &i64s(f, key));
    }
}

fn cohesive_type(name: &str) -> ElementType {
    ElementType::ALL
        .into_iter()
        .find(|t| t.name() == name)
        .unwrap_or_else(|| panic!("element type {name}"))
}

/// The **UD-249** mode of the replay of a TestSMMCFixture case:
/// `law_linear_friction_mode_ii_tetrahedron_4` penetrates with
/// reverse sliding (from step 932), where upstream's residual sliding
/// update differs from the corrected default, so it replays under
/// `friction_residual_sliding_abs`; every other case replays in the
/// default mode (the other three `law_linear_friction_*` cases never slide
/// backwards under penetration and are also replayed under the switch, see
/// [`fixture_cases_bitwise`]; the other laws ignore the switch).
fn friction_residual_sliding_abs(case: &str) -> bool {
    case == "law_linear_friction_mode_ii_tetrahedron_4"
}

/// Replay one TestSMMCFixture case and compare, with the **UD-249** switch
/// `friction_residual_sliding_abs` set or not (`friction_abs`).
fn replay_fixture_with(f: &Fixture, compat: bool, friction_abs: bool) -> Report {
    let mut r = Report::default();
    let dim = param(f, "spatial_dimension").as_u64().unwrap() as usize;
    let extrinsic = param(f, "extrinsic").as_bool().unwrap();
    let mode_ii = param(f, "mode_ii").as_bool().unwrap();
    let ct = cohesive_type(param(f, "cohesive_type").as_str().unwrap());
    let nb_steps = param(f, "nb_steps").as_u64().unwrap() as usize;
    let init_factor = param(f, "init_factor").as_f64().unwrap();
    let inc_factor = param(f, "inc_factor").as_f64().unwrap();
    let seed = param(f, "random_seed").as_i64().unwrap();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), dim);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(seed);
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    // UD-040 compat for random facet strengths (see the caller)
    model.ext.compat.sigma_c_zipped_per_quad = compat;
    // UD-249 compat (see `replay_fixture_with`)
    model.ext.compat.friction_residual_sliding_abs = friction_abs;
    // UD-217 compat: the recorded 3-D tangents are upstream's (the checked
    // insertion surface is the y = 0 plane, n₂ = 0, where both agree)
    model.ext.compat.tangent_rotation_2d_in_3d = dim == 3 && extrinsic;
    model
        .init_full(
            &ModelOptions::new(AnalysisMethod::ExplicitLumpedMass),
            extrinsic,
        )
        .unwrap();
    let stable = model.stable_time_step().unwrap();
    let dt = stable * 0.01;
    model.set_time_step(dt, None).unwrap();
    if has(f, "time_step") {
        r.bits("time_step", &[stable, dt], &f64s(f, "time_step"));
    }
    if extrinsic {
        for ft in param(f, "facet_types").as_array().unwrap() {
            let ft = ft.as_str().unwrap();
            let fty = cohesive_type(ft);
            r.bits(
                &format!("init/tangents/{ft}"),
                model
                    .ext
                    .tangents
                    .get(fty, GhostType::NotGhost)
                    .unwrap()
                    .as_slice(),
                &f64s(f, &format!("init/tangents/{ft}")),
            );
            r.bits(
                &format!("init/normals/{ft}"),
                model
                    .ext
                    .facet_fe
                    .normals_on_integration_points(fty, GhostType::NotGhost)
                    .unwrap()
                    .as_slice(),
                &f64s(f, &format!("init/normals/{ft}")),
            );
            let mat = model.cohesive_material("insertion").unwrap();
            r.bits(
                &format!("init/sigma_c/{ft}"),
                mat.array("sigma_c", fty, GhostType::NotGhost)
                    .unwrap()
                    .as_slice(),
                &f64s(f, &format!("init/sigma_c/{ft}")),
            );
        }
    }
    let sigma_c = common::real_param(&model, "insertion", "sigma_c");
    let e = common::real_param(&model, "body", "E");
    let nu = common::real_param(&model, "body", "nu");
    let mut strain: Vec<Real> = if !mode_ii {
        let mut s = match dim {
            1 => vec![1.],
            2 => vec![-nu * (1. + nu), 0., 0., (1. - nu) * (1. + nu)],
            _ => vec![-nu, 0., 0., 0., 1., 0., 0., 0., -nu],
        };
        for x in &mut s {
            *x *= sigma_c / e;
        }
        s
    } else {
        if dim > 1 {
            model.smm.apply_dirichlet_bc(&FlagOnly(1), "sides").unwrap();
        }
        if dim > 2 {
            model.smm.apply_dirichlet_bc(&FlagOnly(2), "sides").unwrap();
        }
        let beta = common::real_param(&model, "insertion", "beta");
        let mut s = match dim {
            1 => vec![1.],
            2 => vec![0., 0., 1. * (1. + nu), 0.],
            _ => {
                let mut v = vec![0.; 9];
                v[3] = 1. * (1. + nu);
                v
            }
        };
        for x in &mut s {
            *x *= 2. * beta * beta * sigma_c / e;
        }
        s
    };
    // `Matrix<Real>{{a, b}, {c, d}}` scalings are element-wise; keep the
    // upstream factor order: (strain · factor) for the initial condition
    let init: Vec<Real> = strain.iter().map(|s| init_factor * s).collect();
    {
        let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
        let mut u = model.smm.displacement_mut().unwrap();
        for (x, ui) in nodes.chunks(dim).zip(u.as_mut_slice().chunks_mut(dim)) {
            for i in 0..dim {
                let mut acc = 0.0;
                for k in 0..dim {
                    acc += init[i + dim * k] * x[k];
                }
                ui[i] = acc;
            }
        }
    }
    r.bits(
        "initial_displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, "initial_displacement"),
    );
    r.ints(
        "initial_blocked_dofs",
        &bools(model.smm.blocked_dofs().unwrap().as_slice()),
        &i64s(f, "initial_blocked_dofs"),
    );
    for s in &mut strain {
        *s = 1. / 300. * (inc_factor * *s);
    }
    let functor = StrainIncrement {
        strain,
        dim,
        dir: if dim == 1 { 0 } else { 1 },
    };
    let digests = param(f, "step_digests").as_array().unwrap();
    let digest_steps = i64s(f, "steps/digest_steps");
    let mut inserted = Vec::new();
    let mut nb_coh = Vec::new();
    let (mut ek, mut ep, mut ed, mut er, mut ec) = (vec![], vec![], vec![], vec![], vec![]);
    let mut first_digest_mismatch = None;
    for step in 0..nb_steps {
        model.smm.apply_dirichlet_bc(&functor, "loading").unwrap();
        model.smm.apply_dirichlet_bc(&functor, "fixed").unwrap();
        let n = if extrinsic {
            model.check_cohesive_stress().unwrap()
        } else {
            0
        };
        inserted.push(n as i64);
        nb_coh.push(mesh.read().unwrap().nb_element(ct, GhostType::NotGhost) as i64);
        model.solve_step(None).unwrap();
        ek.push(model.energy("kinetic").unwrap());
        ep.push(model.energy("potential").unwrap());
        ed.push(model.energy("dissipated").unwrap());
        er.push(model.energy("reversible").unwrap());
        ec.push(model.energy("cohesive contact").unwrap());
        if !digest_steps.contains(&(step as i64)) {
            continue;
        }
        let d = digest(&[
            model.smm.displacement().unwrap().as_slice(),
            model.smm.velocity().unwrap().as_slice(),
            model.smm.acceleration().unwrap().as_slice(),
        ]);
        if let Some(k) = digest_steps.iter().position(|&s| s == step as i64)
            && first_digest_mismatch.is_none()
            && digests[k].as_str() != Some(d.as_str())
        {
            first_digest_mismatch = Some(step);
        }
    }
    r.compared += digest_steps.len();
    if let Some(s) = first_digest_mismatch {
        r.errors
            .push(format!("step state digest differs from step {s}"));
    }
    r.ints("steps/inserted", &inserted, &i64s(f, "steps/inserted"));
    r.ints("steps/nb_cohesive", &nb_coh, &i64s(f, "steps/nb_cohesive"));
    r.bits(
        "steps/energy/kinetic",
        &ek,
        &f64s(f, "steps/energy/kinetic"),
    );
    r.bits(
        "steps/energy/potential",
        &ep,
        &f64s(f, "steps/energy/potential"),
    );
    r.bits(
        "steps/energy/dissipated",
        &ed,
        &f64s(f, "steps/energy/dissipated"),
    );
    r.bits(
        "steps/energy/reversible",
        &er,
        &f64s(f, "steps/energy/reversible"),
    );
    r.bits(
        "steps/energy/cohesive_contact",
        &ec,
        &f64s(f, "steps/energy/cohesive_contact"),
    );
    r.bits(
        "displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, "displacement"),
    );
    r.bits(
        "velocity",
        model.smm.velocity().unwrap().as_slice(),
        &f64s(f, "velocity"),
    );
    r.bits(
        "acceleration",
        model.smm.acceleration().unwrap().as_slice(),
        &f64s(f, "acceleration"),
    );
    r.bits(
        "internal_force",
        model.smm.internal_force().unwrap().as_slice(),
        &f64s(f, "internal_force"),
    );
    r.bits(
        "mass",
        model.smm.mass().unwrap().as_slice(),
        &f64s(f, "mass"),
    );
    r.ints(
        "blocked_dofs",
        &bools(model.smm.blocked_dofs().unwrap().as_slice()),
        &i64s(f, "blocked_dofs"),
    );
    compare_topology(f, &model, &mut r);
    compare_facet_material(f, &model, &mut r);
    let mat = model.cohesive_material("insertion").unwrap();
    compare_internals(f, mat, "insertion", &mut r);
    r.names.extend(["steps/digest_steps".to_owned()]);
    assert_all_compared(f, &r.names, &[]);
    r
}

fn compare_topology(f: &Fixture, model: &SolidMechanicsModelCohesive, r: &mut Report) {
    let m = model.smm.physics.base.mesh.read().unwrap();
    r.bits("mesh/nodes", m.nodes().as_slice(), &f64s(f, "mesh/nodes"));
    for t in param(f, "mesh_types").as_array().unwrap() {
        let t = t.as_str().unwrap();
        let ours: Vec<i64> = m
            .connectivity(cohesive_type(t), GhostType::NotGhost)
            .map(|c| c.as_slice().iter().map(|&x| i64::from(x)).collect())
            .unwrap_or_default();
        r.ints(
            &format!("mesh/connectivity/{t}"),
            &ours,
            &i64s(f, &format!("mesh/connectivity/{t}")),
        );
    }
    let fm = m.mesh_facets().unwrap();
    for t in param(f, "facet_mesh_types").as_array().unwrap() {
        let t = t.as_str().unwrap();
        let ours: Vec<i64> = fm
            .connectivity(cohesive_type(t), GhostType::NotGhost)
            .map(|c| c.as_slice().iter().map(|&x| i64::from(x)).collect())
            .unwrap_or_default();
        r.ints(
            &format!("facets/connectivity/{t}"),
            &ours,
            &i64s(f, &format!("facets/connectivity/{t}")),
        );
    }
    let names: Vec<String> = param(f, "element_type_names")
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect();
    let enc = |e: akantu_core::Element| -> [i64; 3] {
        if e.is_null() {
            return [-1, -1, -1];
        }
        let k = names
            .iter()
            .position(|n| n == e.ty().name())
            .map_or(-2, |k| k as i64);
        [
            k,
            i64::from(e.index()),
            i64::from(e.ghost_type() == GhostType::Ghost),
        ]
    };
    let e2s = fm
        .data()
        .element_lists(akantu_mesh::utils::ELEMENT_TO_SUBELEMENT)
        .unwrap();
    for t in param(f, "facets/element_to_subelement_types")
        .as_array()
        .unwrap()
    {
        let t = t.as_str().unwrap();
        let rows = e2s.get(cohesive_type(t), GhostType::NotGhost).unwrap();
        let mut flat = Vec::new();
        let mut offsets = vec![0i64];
        for row in rows.as_slice() {
            for e in row {
                flat.extend(enc(*e));
            }
            offsets.push((flat.len() / 3) as i64);
        }
        r.ints(
            &format!("facets/element_to_subelement/{t}"),
            &flat,
            &i64s(f, &format!("facets/element_to_subelement/{t}")),
        );
        r.ints(
            &format!("facets/element_to_subelement_offsets/{t}"),
            &offsets,
            &i64s(f, &format!("facets/element_to_subelement_offsets/{t}")),
        );
    }
    let s2e = fm
        .data()
        .element_map(akantu_mesh::utils::SUBELEMENT_TO_ELEMENT)
        .unwrap();
    for t in param(f, "facets/subelement_to_element_types")
        .as_array()
        .unwrap()
    {
        let t = t.as_str().unwrap();
        let flat: Vec<i64> = s2e
            .get(cohesive_type(t), GhostType::NotGhost)
            .map(|a| a.as_slice().iter().flat_map(|e| enc(*e)).collect())
            .unwrap_or_default();
        r.ints(
            &format!("facets/subelement_to_element/{t}"),
            &flat,
            &i64s(f, &format!("facets/subelement_to_element/{t}")),
        );
    }
}

#[test]
fn fixture_cases_bitwise() {
    let _g = common::lock();
    let mut total = 0;
    let mut skipped = 0;
    let mut failures = Vec::new();
    let family = family_cases("fixture_cases_bitwise", &expected_fixture_family());
    for case in &family {
        let case = case.clone();
        // fast tier: the 3-D cases (≈ 90 % of the unoptimised run time)
        // replay in optimised builds or with COH_ALL=1 (release tier)
        if skip_3d() && case.contains("tetrahedron") {
            eprintln!("{case}: skipped in an unoptimised build (release tier or COH_ALL=1)");
            skipped += 1;
            continue;
        }
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        if !param(&f, "upstream_error").is_null() {
            // upstream raises (cohesive_linear_fatigue: element-type dispatch
            // error); the port's law is checked against closed forms in
            // independent_checks.rs
            eprintln!(
                "{case}: upstream error recorded ({})",
                param(&f, "upstream_error").as_str().unwrap_or("")
            );
            continue;
        }
        // random facet strengths with two quadrature points per facet:
        // upstream pairs facet k with strength entry k (UD-040), replayed in
        // compat mode (the corrected default is checked separately)
        let compat = case.starts_with("random_");
        // The UD-249 mode of each replay is explicit
        let friction_abs = friction_residual_sliding_abs(&case);
        let r = replay_fixture_with(&f, compat, friction_abs);
        if friction_abs {
            // the case pins UD-249: without the switch (the corrected
            // default) the replay leaves the oracle once reverse sliding
            // occurs under penetration
            let d = replay_fixture_with(&f, compat, false);
            eprintln!(
                "{case} (UD-249 default): {} mismatching quantities{}",
                d.errors.len(),
                d.errors
                    .first()
                    .map_or(String::new(), |e| format!(" ({e})"))
            );
            assert!(
                !d.errors.is_empty(),
                "{case}: the case must discriminate UD-249"
            );
        } else if case.starts_with("law_linear_friction_") {
            // no reverse sliding under penetration: upstream's update
            // (the switch) gives the default's results bitwise as well
            let u = replay_fixture_with(&f, compat, true);
            eprintln!(
                "{case} (UD-249 switch): {} values compared, {} mismatching quantities",
                u.compared,
                u.errors.len()
            );
            for e in u.errors.iter().take(12) {
                eprintln!("    {e}");
            }
            if !u.errors.is_empty() {
                failures.push(format!("{case} (UD-249 switch)"));
            }
        }
        total += r.compared;
        eprintln!(
            "{case}: {} values compared, {} mismatching quantities",
            r.compared,
            r.errors.len()
        );
        for e in r.errors.iter().take(12) {
            eprintln!("    {e}");
        }
        if !r.errors.is_empty() {
            failures.push(case);
        }
    }
    eprintln!("total {total} values compared");
    assert!(failures.is_empty(), "cases with mismatches: {failures:?}");
    assert_family_total(
        "fixture_cases_bitwise",
        total,
        FIXTURE_FAMILY_VALUES,
        FIXTURE_FAMILY_VALUES_WITHOUT_3D,
        skipped,
    );
}

/// Upstream-defect switches of the implicit replays (set before
/// `init_full`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Switches {
    /// UD-034: upstream's upper-triangle selection of the unsymmetric
    /// cohesive blocks (otherwise `K` is promoted to unsymmetric storage).
    upper_k: bool,
    /// UD-220: upstream's tangent with the base `σc`.
    base_sigma_c: bool,
    /// UD-028: `δ_max` without history (the oracle's exponential case
    /// aborts there).
    no_history: bool,
    /// UD-241: `δ_max` raised at every Newton iterate.
    per_iterate: bool,
    /// UD-224: intrinsic linear-family laws accepted with zero strength.
    zero_strength: bool,
    /// UD-242, UD-243, UD-244: upstream's linear-family
    /// tangent near and on the contact branch, and upstream's uncoupled
    /// tangent.
    upstream_tangent_contact: bool,
    /// UD-245: every history saved at step entry only.
    history_at_step_entry: bool,
    /// UD-247: upstream's implicit friction (contact
    /// from the previous trial's damage, upstream's friction tangent).
    friction_implicit: bool,
    /// UD-249: upstream's residual sliding update.
    friction_abs: bool,
    /// UD-1160 (D-099 (1)): upstream's negative
    /// unloading secant of a failed point in the linear-family tangent.
    failed_secant: bool,
}

impl Switches {
    /// Every upstream behaviour: the bitwise oracle replays.
    const UPSTREAM: Self = Self {
        upper_k: true,
        base_sigma_c: true,
        no_history: true,
        per_iterate: true,
        zero_strength: true,
        upstream_tangent_contact: true,
        history_at_step_entry: true,
        friction_implicit: true,
        friction_abs: true,
        failed_secant: true,
    };
    /// The corrected defaults.
    const DEFAULT: Self = Self {
        upper_k: false,
        base_sigma_c: false,
        no_history: false,
        per_iterate: false,
        zero_strength: false,
        upstream_tangent_contact: false,
        history_at_step_entry: false,
        friction_implicit: false,
        friction_abs: false,
        failed_secant: false,
    };
    /// Upstream's Newton path (UD-034 + UD-220 tangent, UD-242/243/244
    /// contact branch, UD-1160 secant of a failed point) with the corrected
    /// converged `δ_max` history (UD-028, UD-241, UD-245 defaults).
    const UPSTREAM_TANGENT: Self = Self {
        upper_k: true,
        base_sigma_c: true,
        upstream_tangent_contact: true,
        failed_secant: true,
        ..Self::DEFAULT
    };

    fn is_upstream(self) -> bool {
        self == Self::UPSTREAM
    }

    fn apply(self, model: &mut SolidMechanicsModelCohesive) {
        if self.upper_k {
            model
                .set_symmetry_policy(akantu_linalg::SymmetryPolicy::UpstreamUpperSelection)
                .unwrap();
        }
        let c = &mut model.ext.compat;
        c.tangent_base_sigma_c = self.base_sigma_c;
        c.delta_max_without_history = self.no_history;
        c.delta_max_per_iterate = self.per_iterate;
        c.intrinsic_linear_zero_strength = self.zero_strength;
        c.tangent_penetration_sign = self.upstream_tangent_contact;
        c.tangent_contact_normal_stiffness = self.upstream_tangent_contact;
        c.uncoupled_tangent = self.upstream_tangent_contact;
        c.maxima_committed_at_step_entry = self.history_at_step_entry;
        // UD-248: upstream's exponential tangent, with
        // the other upstream tangents
        c.exponential_tangent = self.upstream_tangent_contact;
        c.friction_upstream_implicit = self.friction_implicit;
        c.friction_residual_sliding_abs = self.friction_abs;
        c.tangent_failed_secant = self.failed_secant;
    }
}

/// **UD-1160** (D-099 (1)): the compat replays that reach
/// upstream's negative unloading secant of a failed point (`δ_max > δc`,
/// evaluated below `δ_max`), through UD-241's per-iterate `δ_max` (an
/// overshooting Newton iterate fails the point; 338, 137, 17 and 27
/// evaluations were counted). They replay bitwise with the switch
/// `tangent_failed_secant` (in the upstream set) and must leave the oracle
/// without it (removing the switch's effect makes them fail). No default run of
/// a committed fixture reaches the regime.
const UD1160_CASES: [&str; 4] = [
    "implicit_static_bilinear_triangle_6",
    "adv_c_implicit_mixed_bilinear_kappa2",
    "adv_v57_implicit_bilinear_contact_reversal",
    "adv_v57_implicit_bilinear_standalone_retry",
];

/// The upstream switch set without UD-1160's.
const WITHOUT_FAILED_SECANT: Switches = Switches {
    failed_secant: false,
    ..Switches::UPSTREAM
};

/// A replay of a [`UD1160_CASES`] case with [`WITHOUT_FAILED_SECANT`] must
/// leave the oracle: Newton iterations per solve, final Newton errors
/// (bits) or the final `K` (bits) differ.
fn assert_discriminates_ud1160(
    case: &str,
    (its, oracle_its): (&[i64], &[i64]),
    (errs, oracle_errs): (&[f64], &[f64]),
    (k, oracle_k): (&[Real], &[Real]),
) {
    let first_its = its
        .iter()
        .zip(oracle_its)
        .position(|(a, b)| a != b)
        .or((its.len() != oracle_its.len()).then(|| its.len().min(oracle_its.len())));
    let first_err = errs
        .iter()
        .zip(oracle_errs)
        .position(|(a, b)| a.to_bits() != b.to_bits())
        .or((errs.len() != oracle_errs.len()).then(|| errs.len().min(oracle_errs.len())));
    let k_diff = k.len() != oracle_k.len()
        || k.iter()
            .zip(oracle_k)
            .any(|(a, b)| a.to_bits() != b.to_bits());
    eprintln!(
        "{case} without the UD-1160 switch: first iteration-count difference at solve {first_its:?}, \
         first Newton-error difference at solve {first_err:?}, final K differs: {k_diff}"
    );
    assert!(
        first_its.is_some() || first_err.is_some() || k_diff,
        "{case}: the case must discriminate UD-1160 (tangent_failed_secant)"
    );
}

/// Iterate overshoot of the points of a cohesive law:
/// at each converged step, the largest `(δ_max − max(δ_max
/// of the previous step, δ)) / δc` over the points that are not fully
/// damaged, `δ = √(β²/κ² ‖Δt‖² + Δn²)` from the stored opening (on
/// penetration it holds the tangential part only, as `δ` does). Zero up to
/// round-off when `δ_max` is the converged maximal opening (UD-241 default);
/// positive where an unconverged Newton iterate opened the point further and
/// left its damage (upstream).
struct OvershootProbe {
    law: &'static str,
    beta2_kappa2: Real,
    previous: Vec<Real>,
}

impl OvershootProbe {
    fn new(model: &SolidMechanicsModelCohesive, law: &'static str) -> Self {
        let beta = common::real_param(model, law, "beta");
        let kappa = common::real_param(model, law, "kappa");
        Self {
            law,
            beta2_kappa2: beta * beta / kappa / kappa,
            previous: Self::field(model, law, "delta max"),
        }
    }

    fn field(model: &SolidMechanicsModelCohesive, law: &str, name: &str) -> Vec<Real> {
        let mat = model.cohesive_material(law).unwrap();
        let mut v = Vec::new();
        for ty in mat.cohesive_types(GhostType::NotGhost) {
            v.extend_from_slice(mat.array(name, ty, GhostType::NotGhost).unwrap().as_slice());
        }
        v
    }

    /// The overshoot of the converged step just solved.
    fn step(&mut self, model: &SolidMechanicsModelCohesive) -> Real {
        let dm = Self::field(model, self.law, "delta max");
        let da = Self::field(model, self.law, "damage");
        let dc = Self::field(model, self.law, "delta_c_eff");
        let op = Self::field(model, self.law, "opening");
        let nr = Self::field(model, self.law, "normal");
        let dim = op.len() / dm.len().max(1);
        let mut worst: Real = 0.0;
        for q in 0..dm.len() {
            if da[q] >= 1.0 - 1e-12 {
                continue;
            }
            let o = &op[q * dim..(q + 1) * dim];
            let n = &nr[q * dim..(q + 1) * dim];
            let on: Real = o.iter().zip(n).map(|(a, b)| a * b).sum();
            let t2: Real = o
                .iter()
                .zip(n)
                .map(|(a, b)| (a - on * b) * (a - on * b))
                .sum();
            let delta = (t2 * self.beta2_kappa2 + on * on).sqrt();
            let prev = self.previous.get(q).copied().unwrap_or(0.0);
            worst = worst.nan_max((dm[q] - prev.nan_max(delta)) / dc[q]);
        }
        self.previous = dm;
        worst
    }
}

/// Smallest iterate overshoot (relative to `δc`) that can move a converged
/// step outside the per-step reaction bound of the implicit default checks:
/// an overshoot of `η·δc` changes the softening traction of a point by about
/// `σc·η` (`∂T/∂δ_max ≈ −σc/δc` near `δ ≈ δ_max`), so below the bound's
/// `1e-3·peak` allowance (`peak ≈ σc ×` the interface area) it cannot.
/// A classification threshold (NUMERICAL_VALIDATION, implicit
/// default runs), not a tolerance.
const OVERSHOOT_ADMISSION: Real = 1e-3;

/// Result of [`replay_implicit`].
struct ImplicitRun {
    report: Report,
    /// Newton iterations per step.
    iterations: Vec<i64>,
    /// Top reaction per step.
    reactions: Vec<f64>,
    /// Final Newton error (residual norm of the free equations) per step.
    errors: Vec<f64>,
    /// Iterate overshoot per step ([`OvershootProbe`]; laws with `kappa`).
    overshoot: Vec<f64>,
    /// Number of free (unblocked) equations.
    nb_free: usize,
    /// Values of the final `K` (storage order).
    k_values: Vec<Real>,
}

/// Replay of an `implicit_static_<law>_triangle_6` case: static Newton
/// with the Eigen solver and the upstream-defect switches `sw`; `Err`: the
/// message of a refused `init_full` (UD-224).
fn replay_implicit(f: &Fixture, sw: Switches) -> Result<ImplicitRun, String> {
    use akantu_core::enums::{NonLinearSolverType, SparseSolverType};
    let compat = sw.is_upstream();
    let mut r = Report::default();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let seed = param(f, "random_seed").as_i64().unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(seed);
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    let opts = ModelOptions::new(AnalysisMethod::Static).with_solver_options(
        akantu_solver::ModelSolverOptions {
            non_linear_solver_type: Some(NonLinearSolverType::Auto),
            sparse_solver_type: Some(SparseSolverType::Eigen),
            ..akantu_solver::ModelSolverOptions::default()
        },
    );
    sw.apply(&mut model);
    model.init_full(&opts, false).map_err(|e| e.to_string())?;
    let mut probe = (param(f, "law").as_str() != Some("exponential"))
        .then(|| OvershootProbe::new(&model, "cohesive"));
    let mut overshoot = Vec::new();
    let tol = akantu_core::math::DEFAULT_TOLERANCE;
    let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
    let nb_nodes = nodes.len() / 2;
    {
        let blocked = model
            .smm
            .blocked_dofs_mut()
            .unwrap()
            .as_mut_slice()
            .to_vec();
        let mut bl = blocked;
        let mut disp = model.smm.displacement().unwrap().as_slice().to_vec();
        for n in 0..nb_nodes {
            let (x, y) = (nodes[2 * n], nodes[2 * n + 1]);
            if y.abs() < tol {
                bl[2 * n + 1] = true;
                disp[2 * n + 1] = 0.0;
            }
            if x.abs() < tol && y < 1.1 {
                bl[2 * n] = true;
                disp[2 * n] = 0.0;
            }
            if (x - 1.).abs() < tol && (y - 1.).abs() < tol {
                bl[2 * n] = true;
                disp[2 * n] = 0.0;
            }
            if (y - 2.).abs() < tol {
                bl[2 * n + 1] = true;
            }
        }
        model
            .smm
            .blocked_dofs_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&bl);
        model
            .smm
            .displacement_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&disp);
    }
    {
        let nls = model.smm.solver.non_linear_solver_mut(None).unwrap();
        nls.set_param("max_iterations", akantu_parser::param::ParamValue::Int(100))
            .unwrap();
        nls.set_param("threshold", akantu_parser::param::ParamValue::Real(1e-5))
            .unwrap();
        nls.set_param(
            "convergence_type",
            akantu_parser::param::ParamValue::Enum("residual".into()),
        )
        .unwrap();
    }
    let increment = 3. / 200.;
    let (mut its, mut errs, mut resids, mut openings) = (vec![], vec![], vec![], vec![]);
    let digests = param(f, "step_digests").as_array().unwrap();
    let mut first_digest = None;
    let nsteps = i64s(f, "steps/nb_iterations")
        .len()
        .max(if has(f, "displacement") { 200 } else { 0 });
    let nsteps = if param(f, "upstream_error").is_null() {
        nsteps
    } else {
        200
    };
    for step in 0..nsteps {
        {
            let mut u_g = model.smm.displacement_mut().unwrap();
            let u = u_g.as_mut_slice();
            for n in 0..nb_nodes {
                if (nodes[2 * n + 1] - 2.).abs() < tol {
                    u[2 * n + 1] += increment;
                }
            }
        }
        model.solve_step(None).unwrap();
        if let Some(p) = probe.as_mut() {
            overshoot.push(p.step(&model));
        }
        let nls = model.smm.solver.non_linear_solver(None).unwrap();
        its.push(nls.nb_iterations() as i64);
        errs.push(nls.error());
        let fi_g = model.smm.internal_force().unwrap();
        let fi = fi_g.as_slice();
        let mut resid = 0.0;
        for n in 0..nb_nodes {
            if (nodes[2 * n + 1] - 2.).abs() / 2. < tol {
                resid += fi[2 * n + 1];
            }
        }
        resids.push(resid);
        let op = model
            .cohesive_material("cohesive")
            .unwrap()
            .array("opening", ElementType::Cohesive2d6, GhostType::NotGhost)
            .unwrap()
            .as_slice()[1];
        openings.push(op);
        if let Some(d) = digests.get(step)
            && first_digest.is_none()
            && d.as_str() != Some(digest(&[model.smm.displacement().unwrap().as_slice()]).as_str())
        {
            first_digest = Some(step);
        }
    }
    let nb_free = model
        .smm
        .blocked_dofs()
        .unwrap()
        .as_slice()
        .iter()
        .filter(|b| !**b)
        .count();
    let k_values = model
        .smm
        .dof_manager()
        .matrix("K")
        .unwrap()
        .coo()
        .2
        .to_vec();
    if !param(f, "upstream_error").is_null() {
        return Ok(ImplicitRun {
            report: r,
            iterations: its,
            reactions: resids,
            errors: errs,
            overshoot,
            nb_free,
            k_values,
        });
    }
    if let Some(s) = first_digest {
        r.errors
            .push(format!("displacement digest differs from step {s}"));
    }
    r.compared += digests.len();
    r.ints("steps/nb_iterations", &its, &i64s(f, "steps/nb_iterations"));
    r.bits("steps/error", &errs, &f64s(f, "steps/error"));
    r.bits(
        "steps/top_reaction",
        &resids,
        &f64s(f, "steps/top_reaction"),
    );
    r.bits(
        "steps/opening_0_y",
        &openings,
        &f64s(f, "steps/opening_0_y"),
    );
    r.bits(
        "displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, "displacement"),
    );
    r.bits(
        "internal_force",
        model.smm.internal_force().unwrap().as_slice(),
        &f64s(f, "internal_force"),
    );
    r.ints(
        "blocked_dofs",
        &bools(model.smm.blocked_dofs().unwrap().as_slice()),
        &i64s(f, "blocked_dofs"),
    );
    let mut skip: Vec<&str> = Vec::new();
    if compat {
        // upstream's symmetric AIJ (UD-034 upper selection), storage order
        let k = model.smm.dof_manager().matrix("K").unwrap();
        let (rows, cols, vals) = k.coo();
        r.ints("K/rows", rows, &i64s(f, "K/rows"));
        r.ints("K/cols", cols, &i64s(f, "K/cols"));
        r.bits("K/values", vals, &f64s(f, "K/values"));
        if param(f, "K/symmetric").as_bool()
            != Some(k.matrix_type() == akantu_core::enums::MatrixType::Symmetric)
        {
            r.errors.push("K/symmetric differs".into());
        }
    } else {
        skip.push("K/*");
    }
    {
        let m = mesh.read().unwrap();
        r.bits("mesh/nodes", m.nodes().as_slice(), &f64s(f, "mesh/nodes"));
        for t in param(f, "mesh_types").as_array().unwrap() {
            let t = t.as_str().unwrap();
            let ours: Vec<i64> = m
                .connectivity(cohesive_type(t), GhostType::NotGhost)
                .map(|c| c.as_slice().iter().map(|&x| i64::from(x)).collect())
                .unwrap_or_default();
            let key = format!("mesh/connectivity/{t}");
            r.ints(&key, &ours, &i64s(f, &key));
        }
    }
    let mat = model.cohesive_material("cohesive").unwrap();
    compare_internals(f, mat, "cohesive", &mut r);
    if compat {
        assert_all_compared(f, &r.names, &skip);
    }
    Ok(ImplicitRun {
        report: r,
        iterations: its,
        reactions: resids,
        errors: errs,
        overshoot,
        nb_free,
        k_values,
    })
}

#[test]
fn implicit_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let expected: Vec<String> = IMPLICIT_FAMILY.iter().map(|s| (*s).to_owned()).collect();
    for case in family_cases("implicit_cases", &expected) {
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        if !param(&f, "upstream_error").is_null() {
            // UD-028: upstream aborts (no delta max history); the port
            // enables the history by default and runs the case
            let run = replay_implicit(&f, Switches::DEFAULT).unwrap();
            eprintln!(
                "{case}: upstream error ({}); default port: {} steps, max {} iterations, final reaction {:e}",
                param(&f, "upstream_error").as_str().unwrap_or(""),
                run.iterations.len(),
                run.iterations.iter().max().unwrap_or(&0),
                run.reactions.last().unwrap_or(&0.0)
            );
            continue;
        }
        let c = replay_implicit(&f, Switches::UPSTREAM).unwrap();
        if UD1160_CASES.contains(&case.as_str()) {
            let u = replay_implicit(&f, WITHOUT_FAILED_SECANT).unwrap();
            assert_discriminates_ud1160(
                &case,
                (&u.iterations, &i64s(&f, "steps/nb_iterations")),
                (&u.errors, &f64s(&f, "steps/error")),
                (&u.k_values, &f64s(&f, "K/values")),
            );
        }
        let r = &c.report;
        total += r.compared;
        eprintln!(
            "{case} (UD-034/UD-220/UD-028/UD-241/UD-224 compat): {} values compared, {} mismatching",
            r.compared,
            r.errors.len()
        );
        for e in r.errors.iter().take(10) {
            eprintln!("    {e}");
        }
        if !r.errors.is_empty() {
            failures.push(case.clone());
        }
        if param(&f, "law").as_str() == Some("linear") {
            // UD-224: an intrinsic `cohesive_linear` has
            // no strength (σc,eff = 0, recorded by the oracle); refused by
            // default — the case is evidence for the compat path only
            let e = replay_implicit(&f, Switches::DEFAULT)
                .err()
                .unwrap_or_else(|| panic!("{case}: the default must refuse (UD-224)"));
            assert!(
                e.contains("UD-224") && e.contains("'cohesive' (cohesive_linear"),
                "{case}: {e}"
            );
            eprintln!("{case} (default): refused (UD-224)");
            continue;
        }
        // default mode: promoted K (UD-034), σc,eff tangent (UD-220),
        // converged δ_max history (UD-028, UD-241) — a different Newton path
        // to the same equilibrium; sanity bound per step (NUMERICAL_VALIDATION,
        // Implicit default runs): the top reaction is `Σ r_y` over the
        // free equations of the top body minus the cohesive force, so two runs
        // stopped at residual norms e_a and e_b differ by at most
        // `√n_free·(e_a + e_b)` plus the difference of their cohesive forces,
        // for which `1e-3` of the peak reaction is a sanity allowance
        // (not derived)
        let d = replay_implicit(&f, Switches::DEFAULT).unwrap();
        let oracle = f64s(&f, "steps/top_reaction");
        let oracle_err = f64s(&f, "steps/error");
        let scale = oracle.iter().fold(0.0_f64, |m, v| m.nan_max(v.abs()));
        let sqrt_n = (d.nb_free as f64).sqrt();
        let mut worst: f64 = 0.0;
        for (k, ((a, b), (ea, eb))) in d
            .reactions
            .iter()
            .zip(&oracle)
            .zip(d.errors.iter().zip(&oracle_err))
            .enumerate()
        {
            let bound = 1e-3 * scale + sqrt_n * (ea + eb);
            let diff = (a - b).abs();
            worst = worst.nan_max(diff / bound);
            assert!(
                diff <= bound,
                "{case}: step {k}: default reaction {a:e} vs oracle {b:e} (bound {bound:e}); \
                 iterate overshoot default {:e} oracle {:e}",
                d.overshoot[k],
                c.overshoot[k]
            );
        }
        assert_eq!(d.reactions.len(), oracle.len(), "{case}: steps");
        // UD-241: the default δ_max is the converged maximal opening (no
        // iterate overshoot; the probe recomputes δ in another summation
        // order: round-off of a few ulp of δ/δc = O(1))
        let worst_d = d.overshoot.iter().fold(0.0_f64, |m, &v| m.nan_max(v));
        assert!(
            worst_d <= 1e-12,
            "{case}: default iterate overshoot {worst_d:e}"
        );
        let worst_c = c.overshoot.iter().fold(0.0_f64, |m, &v| m.nan_max(v));
        eprintln!(
            "{case} (default): iterations {} vs oracle {}, worst reaction difference {worst:.3e} of the per-step bound (peak reaction {scale:e}); iterate overshoot default {worst_d:.1e}, oracle (compat) {worst_c:.3e} δc",
            d.iterations.iter().sum::<i64>(),
            i64s(&f, "steps/nb_iterations").iter().sum::<i64>()
        );
    }
    assert!(failures.is_empty(), "{failures:?}");
    assert_family_total(
        "implicit_cases",
        total,
        IMPLICIT_FAMILY_VALUES,
        IMPLICIT_FAMILY_VALUES,
        0,
    );
}

/// Port of test_cohesive_buildfragments (fragment counts, total mass,
/// fragment centres and velocities) and bitwise replay of the oracle case.
#[test]
fn buildfragments() {
    use akantu_core::enums::SpatialDirection;
    use akantu_model::boundary_condition::{FixedValue, IncrementValue};
    let _g = common::lock();
    let case = family_cases("buildfragments", &["buildfragments".to_owned()]);
    if case.is_empty() {
        // a COH_CASES subset without this case
        return;
    }
    let f = open("buildfragments").expect("buildfragments: oracle case missing");
    assert_upstream_error_status("buildfragments", &f);
    let mut r = Report::default();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(1);
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    model.set_math_tolerance(1e-14);
    model
        .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    // random strengths with two quadrature points per facet: upstream's
    // facet/strength pairing (UD-040) for the bitwise replay
    model
        .cohesive_material_mut("cohesive")
        .unwrap()
        .core
        .compat
        .sigma_c_zipped_per_quad = true;
    let stable = model.stable_time_step().unwrap();
    let dt = stable * 0.05;
    model.set_time_step(dt, None).unwrap();
    r.bits("time_step", &[stable, dt], &f64s(&f, "time_step"));
    let (strain_rate, l): (Real, Real) = (1.0e5, 0.03);
    let disp_increment = strain_rate * l / 2. * dt;
    model.smm.assemble_mass_lumped().unwrap();
    let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
    {
        let mut v_g = model.smm.velocity_mut().unwrap();
        let v = v_g.as_mut_slice();
        for n in 0..nodes.len() / 2 {
            v[2 * n] = strain_rate * nodes[2 * n];
        }
    }
    let fix = FixedValue {
        value: 0.,
        axis: SpatialDirection::X,
    };
    model.smm.apply_dirichlet_bc(&fix, "Left_side").unwrap();
    model.smm.apply_dirichlet_bc(&fix, "Right_side").unwrap();
    let mut fm = akantu_cohesive::FragmentManager::new(&model).unwrap();
    // upstream pairs groups (name order) with centres (index order)
    fm.upstream_compat_inertia_name_order = true;
    let theoretical_mass = l * l / 20. * 2500.;
    let (mut inserted, mut nbf, mut total) = (vec![], vec![], vec![]);
    for _ in 1..=200 {
        inserted.push(model.check_cohesive_stress().unwrap() as i64);
        model.solve_step(None).unwrap();
        let left = IncrementValue {
            value: -disp_increment,
            axis: SpatialDirection::X,
        };
        let right = IncrementValue {
            value: disp_increment,
            axis: SpatialDirection::X,
        };
        model.smm.apply_dirichlet_bc(&left, "Left_side").unwrap();
        model.smm.apply_dirichlet_bc(&right, "Right_side").unwrap();
        fm.compute_all_data(&mut model, 1.).unwrap();
        nbf.push(fm.nb_fragment() as i64);
        let mut tm = 0.;
        for k in 0..fm.nb_fragment() {
            tm += fm.mass[2 * k];
        }
        total.push(tm);
        // upstream assertions: fragments = 1 + fully broken cohesive
        // elements; total mass = L²/20 · ρ
        let mat = model.cohesive_material("cohesive").unwrap();
        let d = mat
            .array("damage", ElementType::Cohesive2d4, GhostType::NotGhost)
            .map(|a| a.as_slice().to_vec())
            .unwrap_or_default();
        let nq = 1.max(
            d.len()
                / mesh
                    .read()
                    .unwrap()
                    .nb_element(ElementType::Cohesive2d4, GhostType::NotGhost)
                    .max(1),
        );
        let broken = d
            .chunks(nq)
            .filter(|c| {
                c.iter()
                    .all(|x| akantu_core::math::are_float_equal(*x, 1., 1e-14))
            })
            .count();
        assert_eq!(fm.nb_fragment(), 1 + broken);
        assert!(
            akantu_core::math::are_float_equal(theoretical_mass, tm, 1e-14),
            "mass {tm} vs {theoretical_mass}"
        );
    }
    // upstream: equal-length fragments — centre of fragment k at
    // `−L/2 + l_f/2 + k·l_f` (`are_float_equal`, tolerance 1e-14) and its
    // x-velocity equal to `centre · strain_rate` (tolerance 100, set by
    // upstream before that check)
    let nb = fm.nb_fragment();
    let flen = l / nb as Real;
    for k in 0..nb {
        let c_th = -l / 2. + flen / 2. + flen * k as Real;
        let c = fm.mass_center[2 * k];
        assert!(
            akantu_core::math::are_float_equal(c, c_th, 1e-14),
            "fragment {k}: centre {c:e} vs {c_th:e}"
        );
        let v = fm.velocity[2 * k];
        assert!(
            akantu_core::math::are_float_equal(v, c * strain_rate, 100.),
            "fragment {k}: velocity {v:e} vs {:e}",
            c * strain_rate
        );
    }
    r.ints("steps/inserted", &inserted, &i64s(&f, "steps/inserted"));
    r.ints("steps/nb_fragments", &nbf, &i64s(&f, "steps/nb_fragments"));
    r.bits("steps/total_mass", &total, &f64s(&f, "steps/total_mass"));
    r.bits("fragments/mass", &fm.mass, &f64s(&f, "fragments/mass"));
    r.bits(
        "fragments/center_of_mass",
        &fm.mass_center,
        &f64s(&f, "fragments/center_of_mass"),
    );
    r.bits(
        "fragments/velocity",
        &fm.velocity,
        &f64s(&f, "fragments/velocity"),
    );
    r.bits(
        "fragments/moments_of_inertia",
        &fm.inertia_moments,
        &f64s(&f, "fragments/moments_of_inertia"),
    );
    r.bits(
        "fragments/principal_directions",
        &fm.principal_directions,
        &f64s(&f, "fragments/principal_directions"),
    );
    let ne: Vec<i64> = fm
        .nb_elements_per_fragment
        .iter()
        .map(|&x| x as i64)
        .collect();
    r.ints(
        "fragments/nb_elements",
        &ne,
        &i64s(&f, "fragments/nb_elements"),
    );
    r.bits(
        "displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(&f, "displacement"),
    );
    r.bits(
        "velocity",
        model.smm.velocity().unwrap().as_slice(),
        &f64s(&f, "velocity"),
    );
    // fragment element lists (type-major within a fragment, as upstream's
    // element groups), encoded with the case's type names
    {
        let names: Vec<String> = param(&f, "element_type_names")
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect();
        let (mut flat, mut offsets) = (Vec::new(), vec![0i64]);
        for frag in &fm.fragments {
            let mut els = frag.clone();
            els.sort_by_key(|e| e.ty());
            for e in els {
                let k = names
                    .iter()
                    .position(|n| n == e.ty().name())
                    .map_or(-2, |k| k as i64);
                flat.extend([
                    k,
                    i64::from(e.index()),
                    i64::from(e.ghost_type() == GhostType::Ghost),
                ]);
            }
            offsets.push((flat.len() / 3) as i64);
        }
        r.ints("fragments/elements", &flat, &i64s(&f, "fragments/elements"));
        r.ints(
            "fragments/elements_offsets",
            &offsets,
            &i64s(&f, "fragments/elements_offsets"),
        );
    }
    compare_internals(
        &f,
        model.cohesive_material("cohesive").unwrap(),
        "cohesive",
        &mut r,
    );
    assert_all_compared(&f, &r.names, &[]);
    eprintln!(
        "buildfragments: {} values compared, {} mismatching; {nb} fragments",
        r.compared,
        r.errors.len()
    );
    for e in &r.errors {
        eprintln!("    {e}");
    }
    assert!(r.errors.is_empty());
    assert_family_total(
        "buildfragments",
        r.compared,
        BUILDFRAGMENTS_VALUES,
        BUILDFRAGMENTS_VALUES,
        0,
    );
}

/// Replay of an adversarial explicit case (`adv_a_*`,
/// `adv_b_*`): the probe's schedule of `StrainIncrement(k · inc)` on
/// `loading` and `fixed`, `checkCohesiveStress`, `solveStep`. `compat`
/// selects upstream's facet/strength pairing (UD-040, random strengths
/// with several points per facet) and, in 3-D, upstream's tangents
/// (UD-217); the default-mode run is reported, not compared.
fn replay_adversarial_explicit(f: &Fixture, compat: bool) -> (Report, Vec<i64>) {
    use akantu_cohesive::selector::MeshDataMaterialCohesiveSelector;
    use akantu_model::constitutive_law::{ElementDataSelector, LawIndexSelector, SelectorChain};
    let mut r = Report::default();
    let dim = param(f, "spatial_dimension").as_u64().unwrap() as usize;
    let ct = cohesive_type(param(f, "cohesive_type").as_str().unwrap());
    let seed = param(f, "random_seed").as_i64().unwrap();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), dim);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(seed);
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    if param(f, "mesh_data_selector").as_bool() == Some(true) {
        // upstream MeshDataMaterialCohesiveSelector with its bulk fallback
        // MeshDataMaterialSelector("physical_names")
        let default = model.default_cohesive_selector();
        model.set_material_selector_chain(SelectorChain {
            selectors: vec![
                Box::new(MeshDataMaterialCohesiveSelector { default }),
                Box::new(ElementDataSelector {
                    name: "physical_names".into(),
                }),
                Box::new(LawIndexSelector),
            ],
            fallback_value: 0,
        });
    }
    model.ext.compat.sigma_c_zipped_per_quad = compat;
    model.ext.compat.tangent_rotation_2d_in_3d = compat && dim == 3;
    model
        .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    let stable = model.stable_time_step().unwrap();
    let dt = stable * param(f, "time_step_factor").as_f64().unwrap();
    model.set_time_step(dt, None).unwrap();
    r.bits("time_step", &[stable, dt], &f64s(f, "time_step"));
    let laws: Vec<String> = param(f, "laws")
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect();
    for ft in param(f, "facet_types").as_array().unwrap() {
        let ft = ft.as_str().unwrap();
        let fty = cohesive_type(ft);
        r.bits(
            &format!("init/tangents/{ft}"),
            model
                .ext
                .tangents
                .get(fty, GhostType::NotGhost)
                .unwrap()
                .as_slice(),
            &f64s(f, &format!("init/tangents/{ft}")),
        );
        r.bits(
            &format!("init/normals/{ft}"),
            model
                .ext
                .facet_fe
                .normals_on_integration_points(fty, GhostType::NotGhost)
                .unwrap()
                .as_slice(),
            &f64s(f, &format!("init/normals/{ft}")),
        );
        for law in &laws {
            let key = format!("init/sigma_c/{law}/{ft}");
            if !has(f, &key) {
                continue;
            }
            let mat = model.cohesive_material(law).unwrap();
            let ours = mat
                .array("sigma_c", fty, GhostType::NotGhost)
                .map(|a| a.as_slice().to_vec())
                .unwrap_or_default();
            r.bits(&key, &ours, &f64s(f, &key));
        }
    }
    // strain = rows · scale (element-wise), column-major here
    let rows: Vec<f64> = param(f, "strain_rows")
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect();
    let scale = param(f, "strain_scale").as_f64().unwrap();
    let mut strain = vec![0.0; dim * dim];
    for i in 0..dim {
        for j in 0..dim {
            strain[i + dim * j] = rows[i * dim + j] * scale;
        }
    }
    let init_factor = param(f, "init_factor").as_f64().unwrap();
    let init: Vec<Real> = strain.iter().map(|s| init_factor * s).collect();
    {
        let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
        let mut u = model.smm.displacement_mut().unwrap();
        for (x, ui) in nodes.chunks(dim).zip(u.as_mut_slice().chunks_mut(dim)) {
            for i in 0..dim {
                let mut acc = 0.0;
                for k in 0..dim {
                    acc += init[i + dim * k] * x[k];
                }
                ui[i] = acc;
            }
        }
    }
    r.bits(
        "initial_displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, "initial_displacement"),
    );
    let inc_factor = param(f, "inc_factor").as_f64().unwrap();
    let inc: Vec<Real> = strain.iter().map(|s| inc_factor * s).collect();
    let digests = param(f, "step_digests").as_array().unwrap();
    let digest_steps = i64s(f, "steps/digest_steps");
    let (mut inserted, mut nb_coh) = (Vec::new(), Vec::new());
    let (mut ek, mut ep, mut ed, mut er, mut ec) = (vec![], vec![], vec![], vec![], vec![]);
    let mut first_digest_mismatch = None;
    let mut step = 0usize;
    for phase in param(f, "schedule").as_array().unwrap() {
        let k = phase[0].as_f64().unwrap();
        let n = phase[1].as_u64().unwrap() as usize;
        let functor = StrainIncrement {
            strain: inc.iter().map(|s| k * s).collect(),
            dim,
            dir: 1,
        };
        for _ in 0..n {
            model.smm.apply_dirichlet_bc(&functor, "loading").unwrap();
            model.smm.apply_dirichlet_bc(&functor, "fixed").unwrap();
            inserted.push(model.check_cohesive_stress().unwrap() as i64);
            nb_coh.push(mesh.read().unwrap().nb_element(ct, GhostType::NotGhost) as i64);
            model.solve_step(None).unwrap();
            ek.push(model.energy("kinetic").unwrap());
            ep.push(model.energy("potential").unwrap());
            ed.push(model.energy("dissipated").unwrap());
            er.push(model.energy("reversible").unwrap());
            ec.push(model.energy("cohesive contact").unwrap());
            if let Some(kk) = digest_steps.iter().position(|&s| s == step as i64) {
                let d = digest(&[
                    model.smm.displacement().unwrap().as_slice(),
                    model.smm.velocity().unwrap().as_slice(),
                    model.smm.acceleration().unwrap().as_slice(),
                ]);
                if first_digest_mismatch.is_none() && digests[kk].as_str() != Some(d.as_str()) {
                    first_digest_mismatch = Some(step);
                }
            }
            step += 1;
        }
    }
    r.compared += digest_steps.len();
    r.names.push("steps/digest_steps".into());
    if let Some(s) = first_digest_mismatch {
        r.errors
            .push(format!("step state digest differs from step {s}"));
    }
    r.ints("steps/inserted", &inserted, &i64s(f, "steps/inserted"));
    r.ints("steps/nb_cohesive", &nb_coh, &i64s(f, "steps/nb_cohesive"));
    for (name, v) in [
        ("kinetic", &ek),
        ("potential", &ep),
        ("dissipated", &ed),
        ("reversible", &er),
        ("cohesive_contact", &ec),
    ] {
        let key = format!("steps/energy/{name}");
        r.bits(&key, v, &f64s(f, &key));
    }
    for (key, ours) in [
        ("displacement", model.smm.displacement().unwrap().as_slice()),
        ("velocity", model.smm.velocity().unwrap().as_slice()),
        ("acceleration", model.smm.acceleration().unwrap().as_slice()),
        (
            "internal_force",
            model.smm.internal_force().unwrap().as_slice(),
        ),
        ("mass", model.smm.mass().unwrap().as_slice()),
    ] {
        r.bits(key, ours, &f64s(f, key));
    }
    r.ints(
        "blocked_dofs",
        &bools(model.smm.blocked_dofs().unwrap().as_slice()),
        &i64s(f, "blocked_dofs"),
    );
    compare_topology(f, &model, &mut r);
    compare_facet_material(f, &model, &mut r);
    for law in &laws {
        compare_internals(f, model.cohesive_material(law).unwrap(), law, &mut r);
    }
    if compat {
        assert_all_compared(f, &r.names, &[]);
    }
    (r, inserted)
}

#[test]
fn adversarial_explicit_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let mut skipped = 0;
    let expected: Vec<String> = ADV_EXPLICIT_FAMILY
        .iter()
        .map(|s| (*s).to_owned())
        .collect();
    for case in family_cases("adversarial_explicit_cases", &expected) {
        if skip_3d() {
            eprintln!("{case}: skipped in an unoptimised build (release tier or COH_ALL=1)");
            skipped += 1;
            continue;
        }
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        let (r, ins) = replay_adversarial_explicit(&f, true);
        total += r.compared;
        eprintln!(
            "{case} (compat): {} values compared, {} mismatching quantities, {} insertions",
            r.compared,
            r.errors.len(),
            ins.iter().sum::<i64>()
        );
        for e in r.errors.iter().take(12) {
            eprintln!("    {e}");
        }
        if !r.errors.is_empty() {
            failures.push(case.clone());
        }
        let (_, ins_d) = replay_adversarial_explicit(&f, false);
        let n_d = ins_d.iter().sum::<i64>();
        eprintln!(
            "{case} (default: UD-040 mean strength, UD-217 orthogonal tangents): {n_d} insertions"
        );
        // regression values of the corrected defaults
        // (A: orthonormal 3-D frames, UD-217; B:
        // facet threshold on the mean of its points' strengths, UD-040)
        let expected = match case.as_str() {
            "adv_a_tet4_multilaw_mixed" => 26,
            "adv_b_tri6_cyclic" => 29,
            other => panic!("{other}: no recorded default insertion count"),
        };
        assert_eq!(n_d, expected, "{case}: default insertions");
    }
    assert!(failures.is_empty(), "{failures:?}");
    assert_family_total(
        "adversarial_explicit_cases",
        total,
        ADV_EXPLICIT_FAMILY_VALUES,
        0,
        skipped,
    );
}

/// **crack propagation over several
/// facets**, against the oracle. In `adv_b_tri6_cyclic` (2-D `triangle_6`,
/// every facet checkable, random `σc`, tension, unloading into compression,
/// reloading) the cracks of the oracle run grow facet by facet: from the
/// oracle's own records (the cohesive connectivity, appended in insertion
/// order, the node coordinates and the cohesive count after every step),
/// the insertions fall on at least 20 distinct steps, at least 15 new
/// facets touch a facet cracked at an earlier step (a crack tip advancing
/// or branching, not scattered insertions), and the crack along `y = 0.25`
/// crosses the whole width (`x` from −1 to 1, at least five facets inserted
/// at at least five steps). The port's replay (upstream's facet/strength
/// pairing, UD-040, as `adversarial_explicit_cases`) inserts the same
/// facets at the same steps and matches every recorded quantity bit for
/// bit, the final topology included. The other cohesive tests insert one
/// facet (`independent_checks.rs::linear_extrinsic_envelope_and_unloading`)
/// or every facet at once (`mesh_invariants_under_full_insertion`, the
/// examples' insertion windows).
#[test]
fn crack_propagates_over_several_facets() {
    let _g = common::lock();
    let f = open("adv_b_tri6_cyclic").expect("the oracle case adv_b_tri6_cyclic");
    let nodes = f64s(&f, "mesh/nodes");
    let conn = i64s(&f, "mesh/connectivity/_cohesive_2d_6");
    let nb = i64s(&f, "steps/nb_cohesive");
    let ne = conn.len() / 6;
    assert_eq!(ne as i64, *nb.last().unwrap());
    // the step of each cohesive element (they are appended in insertion order)
    let step_of: Vec<usize> = (0..ne)
        .map(|e| nb.iter().position(|&n| n > e as i64).unwrap())
        .collect();
    assert!(step_of.windows(2).all(|w| w[0] <= w[1]));
    // the end points of its facet (the first two nodes of `cohesive_2d_6`),
    // as coordinates: the doubled nodes of the two crack sides coincide
    let vertex = |n: i64| {
        let n = n as usize;
        // the mesh coordinates carry ±2e-12 of Gmsh rounding: compare on 1e-9
        (
            (nodes[2 * n] * 1e9).round() as i64,
            (nodes[2 * n + 1] * 1e9).round() as i64,
        )
    };
    let ends: Vec<[(i64, i64); 2]> = (0..ne)
        .map(|e| [vertex(conn[6 * e]), vertex(conn[6 * e + 1])])
        .collect();
    let mut distinct = step_of.clone();
    distinct.dedup();
    let mut growth = 0;
    for e in 0..ne {
        let touches_earlier =
            (0..ne).any(|g| step_of[g] < step_of[e] && ends[e].iter().any(|v| ends[g].contains(v)));
        growth += usize::from(touches_earlier);
    }
    // the crack along y = 0.25
    let on_line: Vec<usize> = (0..ne)
        .filter(|&e| ends[e].iter().all(|v| v.1 == 250_000_000))
        .collect();
    let xs: Vec<i64> = on_line.iter().flat_map(|&e| ends[e].map(|v| v.0)).collect();
    let mut line_steps: Vec<usize> = on_line.iter().map(|&e| step_of[e]).collect();
    line_steps.dedup();
    eprintln!(
        "adv_b_tri6_cyclic (oracle): {ne} facets inserted at {} distinct steps, {growth} of them \
         touching a facet cracked earlier; y = 0.25: {} facets at steps {line_steps:?}",
        distinct.len(),
        on_line.len()
    );
    assert!(distinct.len() >= 20, "{} insertion steps", distinct.len());
    assert!(
        growth >= 15,
        "{growth} insertions continue an earlier crack"
    );
    assert!(on_line.len() >= 5 && line_steps.len() >= 5, "{on_line:?}");
    assert_eq!(xs.iter().min(), Some(&-1_000_000_000));
    assert_eq!(xs.iter().max(), Some(&1_000_000_000));
    // the port reproduces it
    let (r, inserted) = replay_adversarial_explicit(&f, true);
    assert!(
        r.errors.is_empty(),
        "{:?}",
        &r.errors[..r.errors.len().min(8)]
    );
    assert_eq!(inserted, i64s(&f, "steps/inserted"));
}

/// Replay of an adversarial implicit case (`adv_c_*`):
/// mixed-mode top displacement, Newton with the Eigen solver and the
/// upstream-defect switches `sw`; a step where Newton does not converge
/// ends the case (recorded upstream). `Err`: the message of a refused
/// `init_full` (UD-224).
fn replay_adversarial_implicit(f: &Fixture, sw: Switches) -> Result<ImplicitMixedRun, String> {
    use akantu_core::enums::{NonLinearSolverType, SparseSolverType};
    let compat = sw.is_upstream();
    let mut r = Report::default();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let seed = param(f, "random_seed").as_i64().unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(seed);
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    sw.apply(&mut model);
    let opts = ModelOptions::new(AnalysisMethod::Static).with_solver_options(
        akantu_solver::ModelSolverOptions {
            non_linear_solver_type: Some(NonLinearSolverType::Auto),
            sparse_solver_type: Some(SparseSolverType::Eigen),
            ..akantu_solver::ModelSolverOptions::default()
        },
    );
    model.init_full(&opts, false).map_err(|e| e.to_string())?;
    let mut probe = OvershootProbe::new(&model, "cohesive");
    let mut overshoot = Vec::new();
    let tol = akantu_core::math::DEFAULT_TOLERANCE;
    let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
    let nb_nodes = nodes.len() / 2;
    {
        let mut bl = model.smm.blocked_dofs().unwrap().as_slice().to_vec();
        let mut disp = model.smm.displacement().unwrap().as_slice().to_vec();
        for n in 0..nb_nodes {
            let (x, y) = (nodes[2 * n], nodes[2 * n + 1]);
            if y.abs() < tol {
                bl[2 * n + 1] = true;
                disp[2 * n + 1] = 0.0;
            }
            if x.abs() < tol && y < 1.1 {
                bl[2 * n] = true;
                disp[2 * n] = 0.0;
            }
            if (x - 1.).abs() < tol && (y - 1.).abs() < tol {
                bl[2 * n] = true;
                disp[2 * n] = 0.0;
            }
            if (y - 2.).abs() < tol {
                bl[2 * n] = true;
                bl[2 * n + 1] = true;
            }
        }
        model
            .smm
            .blocked_dofs_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&bl);
        model
            .smm
            .displacement_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&disp);
    }
    {
        let nls = model.smm.solver.non_linear_solver_mut(None).unwrap();
        nls.set_param("max_iterations", akantu_parser::param::ParamValue::Int(100))
            .unwrap();
        nls.set_param("threshold", akantu_parser::param::ParamValue::Real(1e-5))
            .unwrap();
        nls.set_param(
            "convergence_type",
            akantu_parser::param::ParamValue::Enum("residual".into()),
        )
        .unwrap();
    }
    let ratio = param(f, "ux_ratio").as_f64().unwrap();
    let max_step = param(f, "max_step").as_u64().unwrap() as usize;
    let increment = 3. / 200.;
    let (mut its, mut errs, mut rx, mut ry) = (vec![], vec![], vec![], vec![]);
    let digests = param(f, "step_digests").as_array().unwrap();
    let mut first_digest = None;
    let mut failed_step: i64 = -1;
    for step in 0..max_step {
        {
            let mut u_g = model.smm.displacement_mut().unwrap();
            let u = u_g.as_mut_slice();
            for n in 0..nb_nodes {
                if (nodes[2 * n + 1] - 2.).abs() < tol {
                    u[2 * n + 1] += increment;
                    u[2 * n] += ratio * increment;
                }
            }
        }
        let converged = match model.solve_step(None) {
            Ok(()) => true,
            Err(akantu_core::Error::NotConverged { .. }) => false,
            Err(e) => panic!("{}: step {step}: {e}", f.case_id()),
        };
        overshoot.push(probe.step(&model));
        let nls = model.smm.solver.non_linear_solver(None).unwrap();
        its.push(nls.nb_iterations() as i64);
        errs.push(nls.error());
        let fi_g = model.smm.internal_force().unwrap();
        let fi = fi_g.as_slice();
        let (mut sx, mut sy) = (0.0, 0.0);
        for n in 0..nb_nodes {
            if (nodes[2 * n + 1] - 2.).abs() / 2. < tol {
                sx += fi[2 * n];
                sy += fi[2 * n + 1];
            }
        }
        rx.push(sx);
        ry.push(sy);
        if let Some(d) = digests.get(step)
            && first_digest.is_none()
            && d.as_str() != Some(digest(&[model.smm.displacement().unwrap().as_slice()]).as_str())
        {
            first_digest = Some(step);
        }
        if !converged {
            failed_step = step as i64;
            break;
        }
    }
    let nb_free = model
        .smm
        .blocked_dofs()
        .unwrap()
        .as_slice()
        .iter()
        .filter(|b| !**b)
        .count();
    if compat {
        if let Some(s) = first_digest {
            r.errors
                .push(format!("displacement digest differs from step {s}"));
        }
        r.compared += digests.len();
        if Some(failed_step) != param(f, "upstream_nonconverged_step").as_i64() {
            r.errors.push(format!(
                "non-converged step {failed_step} vs oracle {}",
                param(f, "upstream_nonconverged_step")
            ));
        }
        r.ints("steps/nb_iterations", &its, &i64s(f, "steps/nb_iterations"));
        r.bits("steps/error", &errs, &f64s(f, "steps/error"));
        r.bits(
            "steps/top_reaction_x",
            &rx,
            &f64s(f, "steps/top_reaction_x"),
        );
        r.bits(
            "steps/top_reaction_y",
            &ry,
            &f64s(f, "steps/top_reaction_y"),
        );
        for (key, ours) in [
            ("displacement", model.smm.displacement().unwrap().as_slice()),
            (
                "internal_force",
                model.smm.internal_force().unwrap().as_slice(),
            ),
        ] {
            r.bits(key, ours, &f64s(f, key));
        }
        r.ints(
            "blocked_dofs",
            &bools(model.smm.blocked_dofs().unwrap().as_slice()),
            &i64s(f, "blocked_dofs"),
        );
        let k = model.smm.dof_manager().matrix("K").unwrap();
        let (rows, cols, vals) = k.coo();
        r.ints("K/rows", rows, &i64s(f, "K/rows"));
        r.ints("K/cols", cols, &i64s(f, "K/cols"));
        r.bits("K/values", vals, &f64s(f, "K/values"));
        {
            let m = mesh.read().unwrap();
            r.bits("mesh/nodes", m.nodes().as_slice(), &f64s(f, "mesh/nodes"));
            for t in param(f, "mesh_types").as_array().unwrap() {
                let t = t.as_str().unwrap();
                let ours: Vec<i64> = m
                    .connectivity(cohesive_type(t), GhostType::NotGhost)
                    .map(|c| c.as_slice().iter().map(|&x| i64::from(x)).collect())
                    .unwrap_or_default();
                let key = format!("mesh/connectivity/{t}");
                r.ints(&key, &ours, &i64s(f, &key));
            }
        }
        compare_internals(
            f,
            model.cohesive_material("cohesive").unwrap(),
            "cohesive",
            &mut r,
        );
        assert_all_compared(f, &r.names, &[]);
    }
    let k_values = model
        .smm
        .dof_manager()
        .matrix("K")
        .unwrap()
        .coo()
        .2
        .to_vec();
    Ok(ImplicitMixedRun {
        report: r,
        iterations: its,
        errors: errs,
        reactions: [rx, ry],
        overshoot,
        failed_step,
        nb_free,
        k_values,
    })
}

/// Result of [`replay_adversarial_implicit`].
struct ImplicitMixedRun {
    report: Report,
    iterations: Vec<i64>,
    errors: Vec<f64>,
    reactions: [Vec<f64>; 2],
    /// Iterate overshoot per step ([`OvershootProbe`]).
    overshoot: Vec<f64>,
    failed_step: i64,
    nb_free: usize,
    /// Values of the final `K` (storage order).
    k_values: Vec<Real>,
}

/// Steps (and reaction components) of each converged adversarial implicit
/// case where the default run is outside the per-step bound of
/// `implicit_cases` (regression values). Each is
/// admitted only with an iterate overshoot ≥ [`OVERSHOOT_ADMISSION`] in
/// one of the runs at that step (asserted): C3 step 32, where a Newton
/// iterate of the oracle (upstream's per-iterate δ_max, UD-241, under its
/// inconsistent tangent, UD-220) overshot a softening point and left
/// 1.3e-2 δc of damage.
const ADMITTED_OUTSIDE: &[(&str, &[(usize, usize)])] =
    &[("adv_c_implicit_mixed_bilinear_kappa2", &[(32, 0), (32, 1)])];

#[test]
fn adversarial_implicit_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let expected: Vec<String> = ADV_IMPLICIT_FAMILY
        .iter()
        .map(|s| (*s).to_owned())
        .collect();
    for case in family_cases("adversarial_implicit_cases", &expected) {
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        let c = replay_adversarial_implicit(&f, Switches::UPSTREAM).unwrap();
        if UD1160_CASES.contains(&case.as_str()) {
            let u = replay_adversarial_implicit(&f, WITHOUT_FAILED_SECANT).unwrap();
            assert_discriminates_ud1160(
                &case,
                (&u.iterations, &i64s(&f, "steps/nb_iterations")),
                (&u.errors, &f64s(&f, "steps/error")),
                (&u.k_values, &f64s(&f, "K/values")),
            );
        }
        total += c.report.compared;
        eprintln!(
            "{case} (UD-034/UD-220/UD-028/UD-241/UD-224 compat): {} values compared, {} mismatching; oracle non-converged step {}",
            c.report.compared,
            c.report.errors.len(),
            param(&f, "upstream_nonconverged_step")
        );
        for e in c.report.errors.iter().take(10) {
            eprintln!("    {e}");
        }
        if !c.report.errors.is_empty() {
            failures.push(case.clone());
        }
        let d = match replay_adversarial_implicit(&f, Switches::DEFAULT) {
            Ok(d) => d,
            Err(e) => {
                // UD-224: C1's intrinsic `cohesive_linear`
                // has no strength; refused by default — evidence for the
                // UD-034/UD-220 compat path only (upstream's base-σc tangent
                // is non-zero and unsymmetric there)
                assert!(
                    case.contains("_linear_")
                        && e.contains("UD-224")
                        && e.contains("'cohesive' (cohesive_linear"),
                    "{case}: {e}"
                );
                eprintln!("{case} (default): refused (UD-224)");
                continue;
            }
        };
        assert_eq!(d.failed_step, -1, "{case}: the default run must converge");
        // UD-241: no iterate overshoot in the default run (round-off of the
        // probe's δ, see `implicit_cases`)
        let worst_d = d.overshoot.iter().fold(0.0_f64, |m, &v| m.nan_max(v));
        assert!(
            worst_d <= 1e-12,
            "{case}: default iterate overshoot {worst_d:e}"
        );
        let summary = format!(
            "{case} (default): {} steps, {} iterations (oracle {} in {} steps), final error {:e}",
            d.iterations.len(),
            d.iterations.iter().sum::<i64>(),
            c.iterations.iter().sum::<i64>(),
            c.iterations.len(),
            d.errors.last().unwrap_or(&0.0)
        );
        if std::env::var("COH_DEBUG").is_ok() {
            for k in 0..d.iterations.len().min(c.iterations.len()) {
                eprintln!(
                    "  step {k}: default its {} err {:.3e} rx {:.6e} ry {:.6e} over {:.1e} | compat its {} err {:.3e} rx {:.6e} ry {:.6e} over {:.3e}",
                    d.iterations[k],
                    d.errors[k],
                    d.reactions[0][k],
                    d.reactions[1][k],
                    d.overshoot[k],
                    c.iterations[k],
                    c.errors[k],
                    c.reactions[0][k],
                    c.reactions[1][k],
                    c.overshoot[k]
                );
            }
        }
        if c.failed_step < 0 {
            // both converged: per step, the bound of `implicit_cases`
            // (residual part derived, `1e-3·peak` a sanity allowance);
            // a step outside it must carry an iterate overshoot ≥
            // OVERSHOOT_ADMISSION in one of the runs (the oracle's converged
            // state then holds damage of an unconverged iterate, UD-241), and
            // the outside set must equal the recorded regression values.
            // Also asserted: the peak and the final reactions.
            let sqrt_n = (d.nb_free as f64).sqrt();
            let mut outside = Vec::new();
            for comp in 0..2 {
                let oracle = &c.reactions[comp];
                let ours = &d.reactions[comp];
                let scale = oracle.iter().fold(0.0_f64, |m, v| m.nan_max(v.abs()));
                let peak = ours.iter().fold(0.0_f64, |m, v| m.nan_max(v.abs()));
                assert!(
                    (peak - scale).abs() <= 1e-3 * scale,
                    "{case}: peak reaction {comp}: {peak:e} vs oracle {scale:e}"
                );
                for (k, (a, b)) in ours.iter().zip(oracle).enumerate() {
                    let bound = 1e-3 * scale + sqrt_n * (d.errors[k] + c.errors[k]);
                    if (a - b).abs() > bound {
                        outside.push((k, comp));
                        let over = d.overshoot[k].nan_max(c.overshoot[k]);
                        assert!(
                            over >= OVERSHOOT_ADMISSION,
                            "{case}: step {k} component {comp} outside the bound ({:e} vs {:e}, \
                             bound {bound:e}) without an iterate overshoot (default {:e}, oracle {:e})",
                            a,
                            b,
                            d.overshoot[k],
                            c.overshoot[k]
                        );
                    }
                }
                let k = ours.len() - 1;
                let bound = 1e-3 * scale + sqrt_n * (d.errors[k] + c.errors[k]);
                assert!(
                    (ours[k] - oracle[k]).abs() <= bound,
                    "{case}: final reaction {comp}: {:e} vs {:e} (bound {bound:e})",
                    ours[k],
                    oracle[k]
                );
            }
            outside.sort_unstable();
            let expected = ADMITTED_OUTSIDE
                .iter()
                .find(|(n, _)| *n == case)
                .map_or(&[][..], |(_, v)| *v);
            assert_eq!(
                outside, expected,
                "{case}: steps outside the per-step bound (step, component)"
            );
            let overs: Vec<(usize, f64)> =
                outside.iter().map(|&(k, _)| (k, c.overshoot[k])).collect();
            eprintln!(
                "{summary}; outside the per-step bound (step, component): {outside:?}, oracle iterate overshoot there {overs:?} δc"
            );
        } else {
            eprintln!("{summary}");
        }
    }
    assert!(failures.is_empty(), "{failures:?}");
    assert_family_total(
        "adversarial_implicit_cases",
        total,
        ADV_IMPLICIT_FAMILY_VALUES,
        ADV_IMPLICIT_FAMILY_VALUES,
        0,
    );
}

/// Reactions (per component), final Newton errors and free equations of an
/// implicit replay with the switches `sw`.
fn implicit_path(f: &Fixture, sw: Switches) -> (Vec<Vec<f64>>, Vec<f64>, usize) {
    if f.case_id().contains("/adv_c_") {
        let run = replay_adversarial_implicit(f, sw).unwrap();
        assert_eq!(run.failed_step, -1, "{}: {sw:?} must converge", f.case_id());
        (run.reactions.to_vec(), run.errors, run.nb_free)
    } else {
        let run = replay_implicit(f, sw).unwrap();
        (vec![run.reactions], run.errors, run.nb_free)
    }
}

/// Largest `|R_a − R_b| / (√n_free·(e_a + e_b))` over the steps and
/// components of two implicit paths, with its step.
fn path_difference(
    a: &(Vec<Vec<f64>>, Vec<f64>, usize),
    b: &(Vec<Vec<f64>>, Vec<f64>, usize),
) -> (f64, usize, f64) {
    let sqrt_n = (a.2 as f64).sqrt();
    let (mut worst, mut at, mut abs) = (0.0_f64, 0, 0.0_f64);
    for (ra, rb) in a.0.iter().zip(&b.0) {
        assert_eq!(ra.len(), rb.len());
        for k in 0..ra.len() {
            let diff = (ra[k] - rb[k]).abs();
            let ratio = diff / (sqrt_n * (a.1[k] + b.1[k]));
            if ratio > worst {
                (worst, at, abs) = (ratio, k, diff);
            }
        }
    }
    (worst, at, abs)
}

/// UD-241: independent check of the corrected default:
/// with the converged `δ_max` history the converged state of every step
/// does not depend on the Newton path. Upstream's tangent (UD-220 base σc
/// with UD-034 upper-triangle `K`) and the consistent tangent reach the
/// same reactions within the residual part of the per-step bound,
/// `√n_free·(e_a + e_b)` — without the `1e-3·peak` allowance (the
/// cohesive-force difference of the two converged states is not bounded a
/// priori; observed 0.61 and 0.64 of the residual part). Power: with
/// upstream's per-iterate update the same two paths separate at C3 step 32
/// (observed 6.8e3 times the residual part, |ΔR| = 1.6e-2), so the check
/// detects the path dependence it excludes.
#[test]
fn ud241_converged_state_is_independent_of_the_newton_path() {
    let _g = common::lock();
    for (case, separates_at) in [
        ("adv_c_implicit_mixed_bilinear_kappa2", Some(32)),
        // no iterate overshoots a softening point there (oracle overshoot 0)
        ("implicit_static_bilinear_triangle_6", None),
        // The port-only default implicit exponential run (the
        // oracle records upstream's abort, UD-028): UD-248's consistent
        // tangent and upstream's tangent, both with the committed history,
        // reach the same equilibria
        ("implicit_static_exponential_triangle_6", None),
    ] {
        let f = open(case).unwrap();
        let consistent = implicit_path(&f, Switches::DEFAULT);
        let upstream_tangent = implicit_path(&f, Switches::UPSTREAM_TANGENT);
        let (w, k, abs) = path_difference(&consistent, &upstream_tangent);
        let per_iterate = Switches {
            per_iterate: true,
            ..Switches::DEFAULT
        };
        let consistent_pi = implicit_path(&f, per_iterate);
        let upstream_tangent_pi = implicit_path(
            &f,
            Switches {
                per_iterate: true,
                ..Switches::UPSTREAM_TANGENT
            },
        );
        let (wp, kp, absp) = path_difference(&consistent_pi, &upstream_tangent_pi);
        eprintln!(
            "{case}: converged history: worst {w:.3e} of √n(e_a+e_b) (step {k}, |ΔR| {abs:.3e}); per iterate: worst {wp:.3e} (step {kp}, |ΔR| {absp:.3e})"
        );
        assert!(
            w <= 1.0,
            "{case}: the converged state depends on the Newton path: step {k}, |ΔR| {abs:e} = {w:e} × √n(e_a + e_b)"
        );
        if let Some(step) = separates_at {
            assert!(
                wp > 100.0 && kp == step,
                "{case}: per-iterate paths expected to separate at step {step} (worst {wp:e} at step {kp})"
            );
        }
    }
}

/// Result of [`failed_regime_run`].
struct FailedRegimeRun {
    /// Newton iterations per step.
    iterations: Vec<i64>,
    /// Steps that did not converge.
    not_converged: Vec<usize>,
    /// Converged steps with a point failed past δc (`δ_max > δc,eff`)
    /// evaluated below its `δ_max`, open (no contact traction).
    regime_open: Vec<usize>,
    /// The same with a contact traction (contact after breaking).
    regime_contact: Vec<usize>,
}

/// The run of [`ud1160_implicit_default_run_through_the_failed_regime_converges`]
/// with the switches `sw`.
fn failed_regime_run(sw: Switches) -> FailedRegimeRun {
    use akantu_core::enums::{NonLinearSolverType, SparseSolverType};
    use akantu_parser::param::ParamValue;
    let f = open("implicit_static_bilinear_triangle_6").unwrap();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    // the case's input with contact after breaking
    let input = "model solid_mechanics_model_cohesive [
  cohesive_inserter [
    bounding_box = [[-10, 10], [0.9, 1.1]]
  ]
  material elastic [
    name = steel
    rho = 1
    E = 6
    nu = 0.0
  ]
  material cohesive_bilinear [
    name = cohesive
    sigma_c = 1
    G_c = 0.25
    delta_0 = 0.01
    penalty = 10
    contact_after_breaking = true
  ]
]
";
    let parser = Parser::parse_str(input, "material.dat").unwrap();
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    let opts = ModelOptions::new(AnalysisMethod::Static).with_solver_options(
        akantu_solver::ModelSolverOptions {
            non_linear_solver_type: Some(NonLinearSolverType::Auto),
            sparse_solver_type: Some(SparseSolverType::Eigen),
            ..akantu_solver::ModelSolverOptions::default()
        },
    );
    sw.apply(&mut model);
    model.init_full(&opts, false).unwrap();
    let tol = akantu_core::math::DEFAULT_TOLERANCE;
    let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
    let nb_nodes = nodes.len() / 2;
    // the boundary conditions of `replay_implicit`
    {
        let mut bl = model.smm.blocked_dofs().unwrap().as_slice().to_vec();
        for n in 0..nb_nodes {
            let (x, y) = (nodes[2 * n], nodes[2 * n + 1]);
            if y.abs() < tol || (y - 2.).abs() < tol {
                bl[2 * n + 1] = true;
            }
            if (x.abs() < tol && y < 1.1) || ((x - 1.).abs() < tol && (y - 1.).abs() < tol) {
                bl[2 * n] = true;
            }
        }
        model
            .smm
            .blocked_dofs_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&bl);
        model.smm.displacement_mut().unwrap().fill(0.0);
    }
    {
        let nls = model.smm.solver.non_linear_solver_mut(None).unwrap();
        nls.set_param("max_iterations", ParamValue::Int(100))
            .unwrap();
        nls.set_param("threshold", ParamValue::Real(1e-5)).unwrap();
        nls.set_param("convergence_type", ParamValue::Enum("residual".into()))
            .unwrap();
    }
    let increment = 3. / 200.;
    let mut run = FailedRegimeRun {
        iterations: Vec::new(),
        not_converged: Vec::new(),
        regime_open: Vec::new(),
        regime_contact: Vec::new(),
    };
    let mut step = 0;
    for (sign, steps) in [(1.0, 60), (-1.0, 80), (1.0, 30)] {
        for _ in 0..steps {
            {
                let mut u_g = model.smm.displacement_mut().unwrap();
                let u = u_g.as_mut_slice();
                for n in 0..nb_nodes {
                    if (nodes[2 * n + 1] - 2.).abs() < tol {
                        u[2 * n + 1] += sign * increment;
                    }
                }
            }
            let converged = match model.solve_step(None) {
                Ok(()) => true,
                Err(akantu_core::Error::NotConverged { .. }) => false,
                Err(e) => panic!("step {step}: {e}"),
            };
            let nls = model.smm.solver.non_linear_solver(None).unwrap();
            run.iterations.push(nls.nb_iterations() as i64);
            if converged {
                let mat = model.cohesive_material("cohesive").unwrap();
                let q = |n: &str| {
                    mat.array(n, ElementType::Cohesive2d6, GhostType::NotGhost)
                        .map(|a| a.as_slice().to_vec())
                        .unwrap_or_default()
                };
                let (dm, dc, op, nr, ct) = (
                    q("delta max"),
                    q("delta_c_eff"),
                    q("opening"),
                    q("normal"),
                    q("contact_tractions"),
                );
                let (mut open, mut contact) = (false, false);
                for p in 0..dm.len() {
                    // β = 0: δ = |Δn| (on penetration the stored opening is
                    // the tangential part, δ = 0)
                    let dn = op[2 * p] * nr[2 * p] + op[2 * p + 1] * nr[2 * p + 1];
                    let in_contact = ct[2 * p] != 0.0 || ct[2 * p + 1] != 0.0;
                    let delta = if in_contact { 0.0 } else { dn.abs() };
                    if dm[p] > dc[p] && delta < dm[p] {
                        if in_contact {
                            contact = true;
                        } else {
                            open = true;
                        }
                    }
                }
                if open {
                    run.regime_open.push(step);
                }
                if contact {
                    run.regime_contact.push(step);
                }
            } else {
                run.not_converged.push(step);
            }
            step += 1;
        }
    }
    run
}

/// **UD-1160** (D-099 (1)): an implicit static run of the
/// default mode through the failed regime, which no committed default run
/// reaches: `implicit_static_bilinear_triangle_6`'s mesh, boundary
/// conditions and law (σc 1, G_c 0.25, δ₀ 0.01, penalty 10, Newton with
/// Eigen, residual 1e-5, at most 100 iterations) with
/// `contact_after_breaking`; the top edge is pulled up past complete
/// failure (60 steps of 0.015: δ_max ≈ 0.9 > δc = 0.5), pushed back down
/// through the closed interface into contact (80 steps) and pulled up again
/// (30 steps). After failure every point is evaluated below its `δ_max`,
/// open and in contact. Default: every step converges (173 Newton
/// iterations, at most 2 per step, on aarch64). With upstream's negative
/// secant (the switch `tangent_failed_secant` alone) the Newton iterations
/// of the failed regime use a wrong stiffness while the residual has no
/// cohesive force there: 990 iterations, up to 13 per step.
#[test]
fn ud1160_implicit_default_run_through_the_failed_regime_converges() {
    let _g = common::lock();
    if family_cases(
        "ud1160_implicit_default_run",
        &["implicit_static_bilinear_triangle_6".to_owned()],
    )
    .is_empty()
    {
        // a COH_CASES subset without the case whose mesh this run uses
        return;
    }
    let d = failed_regime_run(Switches::DEFAULT);
    let u = failed_regime_run(Switches {
        failed_secant: true,
        ..Switches::DEFAULT
    });
    for (what, r) in [("default", &d), ("upstream failed secant", &u)] {
        eprintln!(
            "{what}: {} steps, {} iterations (max {}), not converged {:?}; failed regime open at {} steps (first {:?}), in contact at {} (first {:?})",
            r.iterations.len(),
            r.iterations.iter().sum::<i64>(),
            r.iterations.iter().max().unwrap_or(&0),
            r.not_converged,
            r.regime_open.len(),
            r.regime_open.first(),
            r.regime_contact.len(),
            r.regime_contact.first()
        );
    }
    assert!(
        d.not_converged.is_empty(),
        "the default run converges at every step"
    );
    assert!(
        !d.regime_open.is_empty() && !d.regime_contact.is_empty(),
        "the default run reaches the failed regime, open and in contact"
    );
    // the derivative of the zero traction converges in fewer Newton
    // iterations than upstream's secant (observed 173 vs 990)
    let (its_d, its_u): (i64, i64) = (d.iterations.iter().sum(), u.iterations.iter().sum());
    assert!(
        its_d < its_u,
        "Newton iterations: default {its_d}, upstream failed secant {its_u}"
    );
}

/// Result of [`replay_v57_adversarial`].
struct V57Run {
    report: Report,
    /// Newton iterations per solve attempt.
    iterations: Vec<i64>,
    /// Steps of the attempts that did not converge.
    not_converged: Vec<i64>,
    /// Step where the case stopped (non-converged retry), −1 if none.
    failed_step: i64,
    /// Committed (previous) `delta max` before and after the standalone
    /// evaluation (empty without history).
    standalone_history: (Vec<Real>, Vec<Real>),
    /// Steps whose converged state has a non-zero contact traction.
    contact_steps: Vec<i64>,
    /// Converged steps whose friction force (`cohesive_linear_friction`)
    /// at point 0 opposes the tangential opening (reverse sliding).
    reverse_steps: Vec<i64>,
    /// Values of the final `K` (storage order).
    k_values: Vec<Real>,
    /// Final Newton error per solve attempt.
    errors: Vec<f64>,
}

/// Replay of an adversarial implicit case (`adv_v57_*`,
/// probe `v57_case`, adopted): intrinsic
/// `cohesive_bilinear` on `implicit.msh`, a schedule of signed top
/// displacement increments (x moved by `ux_ratio` times y), Newton
/// (residual 1e-5, Eigen), optionally a standalone
/// `assemble_internal_forces` at `u_y + 0.3` after step `standalone_at`
/// (then `u` restored) and a first attempt of step `fail_at` with
/// `max_iterations = 1`, retried with 100. Every solve attempt is recorded.
/// The upstream switch set compares every recorded quantity bitwise.
fn replay_v57_adversarial(f: &Fixture, sw: Switches) -> V57Run {
    use akantu_core::enums::{NonLinearSolverType, SparseSolverType};
    use akantu_parser::param::ParamValue;
    let compat = sw.is_upstream();
    let mut r = Report::default();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    let seed = param(f, "random_seed").as_i64().unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(seed);
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    // The probe activated the history of `delta max`
    // after initFull (UD-028 A: the defined behaviour, which implicit
    // `cohesive_linear_friction` needs), so the replay keeps it whatever
    // the switch set
    let probe_history = param(f, "probe_delta_max_history").as_bool() == Some(true);
    if probe_history {
        Switches {
            no_history: false,
            ..sw
        }
        .apply(&mut model);
    } else {
        sw.apply(&mut model);
    }
    // Extrinsic model, insertion by the stress check at a
    // uniform pre-strain before the first solve
    let prestress = param(f, "prestress_strain").as_f64();
    let opts = ModelOptions::new(AnalysisMethod::Static).with_solver_options(
        akantu_solver::ModelSolverOptions {
            non_linear_solver_type: Some(NonLinearSolverType::Auto),
            sparse_solver_type: Some(SparseSolverType::Eigen),
            ..akantu_solver::ModelSolverOptions::default()
        },
    );
    model.init_full(&opts, prestress.is_some()).unwrap();
    let tol = akantu_core::math::DEFAULT_TOLERANCE;
    let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
    let nb_nodes = nodes.len() / 2;
    // X blocked on the left below the band only, not at
    // (1, 1): the interface can slide
    let free_x = param(f, "interface_free_x").as_bool() == Some(true);
    let y_left = if free_x { 0.9 } else { 1.1 };
    {
        let mut bl = model.smm.blocked_dofs().unwrap().as_slice().to_vec();
        let mut disp = model.smm.displacement().unwrap().as_slice().to_vec();
        for n in 0..nb_nodes {
            let (x, y) = (nodes[2 * n], nodes[2 * n + 1]);
            if y.abs() < tol {
                bl[2 * n + 1] = true;
                disp[2 * n + 1] = 0.0;
            }
            if x.abs() < tol && y < y_left {
                bl[2 * n] = true;
                disp[2 * n] = 0.0;
            }
            if !free_x && (x - 1.).abs() < tol && (y - 1.).abs() < tol {
                bl[2 * n] = true;
                disp[2 * n] = 0.0;
            }
            if (y - 2.).abs() < tol {
                bl[2 * n] = true;
                bl[2 * n + 1] = true;
            }
        }
        model
            .smm
            .blocked_dofs_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&bl);
        model
            .smm
            .displacement_mut()
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&disp);
    }
    if let Some(eps) = prestress {
        {
            let mut u_g = model.smm.displacement_mut().unwrap();
            let u = u_g.as_mut_slice();
            for n in 0..nb_nodes {
                u[2 * n + 1] = eps * nodes[2 * n + 1];
            }
        }
        model.assemble_internal_forces().unwrap();
        let inserted = model.check_cohesive_stress().unwrap();
        if compat {
            // assembled at the pre-strain, then resized by the insertion
            // (the doubled nodes' rows appended)
            r.bits(
                "prestress/internal_force",
                model.smm.internal_force().unwrap().as_slice(),
                &f64s(f, "prestress/internal_force"),
            );
        }
        if Some(inserted as i64) != param(f, "prestress_inserted").as_i64() {
            r.errors.push(format!(
                "pre-strain insertion: {inserted} cohesive elements, oracle {}",
                param(f, "prestress_inserted")
            ));
        }
    }
    let set_its = |model: &mut SolidMechanicsModelCohesive, its: i64| {
        let nls = model.smm.solver.non_linear_solver_mut(None).unwrap();
        nls.set_param("max_iterations", ParamValue::Int(its))
            .unwrap();
        nls.set_param("threshold", ParamValue::Real(1e-5)).unwrap();
        nls.set_param("convergence_type", ParamValue::Enum("residual".into()))
            .unwrap();
    };
    set_its(&mut model, 100);
    let ratio = param(f, "ux_ratio").as_f64().unwrap();
    let standalone_at = param(f, "standalone_at").as_i64().unwrap();
    let fail_at = param(f, "fail_at").as_i64().unwrap();
    // (y sign, steps, x increment in units of the y increment — absent:
    // sign · ux_ratio); the x factors are probe literals (exact in JSON)
    let schedule: Vec<(f64, i64, Option<f64>)> = param(f, "schedule")
        .as_array()
        .unwrap()
        .iter()
        .map(|e| {
            (
                e[0].as_f64().unwrap(),
                e[1].as_i64().unwrap(),
                e.get(2).map(|x| x.as_f64().unwrap()),
            )
        })
        .collect();
    let digests = param(f, "attempt_digests").as_array().unwrap();
    let increment = 3. / 200.;
    let top = |fi: &[f64]| {
        let (mut sx, mut sy) = (0.0, 0.0);
        for n in 0..nb_nodes {
            if (nodes[2 * n + 1] - 2.).abs() / 2. < tol {
                sx += fi[2 * n];
                sy += fi[2 * n + 1];
            }
        }
        (sx, sy)
    };
    let delta_max_previous = |model: &SolidMechanicsModelCohesive| {
        model
            .cohesive_material("cohesive")
            .unwrap()
            .internal("delta max")
            .unwrap()
            .previous(ElementType::Cohesive2d6, GhostType::NotGhost)
            .map(|a| a.as_slice().to_vec())
            .unwrap_or_default()
    };
    let (mut a_step, mut a_conv, mut a_its) = (vec![], vec![], vec![]);
    let (mut a_err, mut a_rx, mut a_ry, mut sa) = (vec![], vec![], vec![], vec![]);
    let mut first_digest = None;
    let mut contact_steps = Vec::new();
    let mut reverse_steps = Vec::new();
    let mut standalone_history = (Vec::new(), Vec::new());
    let mut failed_step: i64 = -1;
    let mut step: i64 = 0;
    'outer: for (sign, steps, x_factor) in schedule {
        for _ in 0..steps {
            {
                let mut u_g = model.smm.displacement_mut().unwrap();
                let u = u_g.as_mut_slice();
                for n in 0..nb_nodes {
                    if (nodes[2 * n + 1] - 2.).abs() < tol {
                        u[2 * n + 1] += sign * increment;
                        u[2 * n] += match x_factor {
                            Some(x) => x * increment,
                            None => sign * ratio * increment,
                        };
                    }
                }
            }
            let mut attempt = |model: &mut SolidMechanicsModelCohesive| -> bool {
                let converged = match model.solve_step(None) {
                    Ok(()) => true,
                    Err(akantu_core::Error::NotConverged { .. }) => false,
                    Err(e) => panic!("{}: step {step}: {e}", f.case_id()),
                };
                let nls = model.smm.solver.non_linear_solver(None).unwrap();
                a_step.push(step);
                a_conv.push(i64::from(converged));
                a_its.push(nls.nb_iterations() as i64);
                a_err.push(nls.error());
                let (sx, sy) = top(model.smm.internal_force().unwrap().as_slice());
                a_rx.push(sx);
                a_ry.push(sy);
                let k = a_step.len() - 1;
                if first_digest.is_none()
                    && digests.get(k).and_then(|d| d.as_str())
                        != Some(digest(&[model.smm.displacement().unwrap().as_slice()]).as_str())
                {
                    first_digest = Some(k);
                }
                if converged
                    && model
                        .cohesive_material("cohesive")
                        .unwrap()
                        .array(
                            "contact_tractions",
                            ElementType::Cohesive2d6,
                            GhostType::NotGhost,
                        )
                        .is_ok_and(|a| a.as_slice().iter().any(|v| *v != 0.0))
                {
                    contact_steps.push(step);
                }
                if converged {
                    let mat = model.cohesive_material("cohesive").unwrap();
                    let q = |n: &str| {
                        mat.array(n, ElementType::Cohesive2d6, GhostType::NotGhost)
                            .map(|a| a.as_slice().to_vec())
                            .unwrap_or_default()
                    };
                    let (fr, op) = (q("friction_force"), q("opening"));
                    if fr.len() >= 2 && fr[0] * op[0] + fr[1] * op[1] < 0.0 {
                        reverse_steps.push(step);
                    }
                }
                converged
            };
            if step == fail_at {
                set_its(&mut model, 1);
                let _ = attempt(&mut model);
                set_its(&mut model, 100);
            }
            if !attempt(&mut model) {
                failed_step = step;
                break 'outer;
            }
            if step == standalone_at {
                let saved = model.smm.displacement().unwrap().as_slice().to_vec();
                {
                    let mut u_g = model.smm.displacement_mut().unwrap();
                    let u = u_g.as_mut_slice();
                    for n in 0..nb_nodes {
                        if (nodes[2 * n + 1] - 2.).abs() < tol {
                            u[2 * n + 1] += 0.3;
                        }
                    }
                }
                let before = delta_max_previous(&model);
                model.assemble_internal_forces().unwrap();
                standalone_history = (before, delta_max_previous(&model));
                let (sx, sy) = top(model.smm.internal_force().unwrap().as_slice());
                sa.push(sx);
                sa.push(sy);
                model
                    .smm
                    .displacement_mut()
                    .unwrap()
                    .as_mut_slice()
                    .copy_from_slice(&saved);
            }
            step += 1;
        }
    }
    let not_converged = a_conv
        .iter()
        .zip(&a_step)
        .filter(|(c, _)| **c == 0)
        .map(|(_, s)| *s)
        .collect();
    if compat {
        if let Some(k) = first_digest {
            r.errors
                .push(format!("displacement digest differs from attempt {k}"));
        }
        r.compared += digests.len();
        if Some(failed_step) != param(f, "upstream_nonconverged_step").as_i64() {
            r.errors.push(format!(
                "non-converged step {failed_step} vs oracle {}",
                param(f, "upstream_nonconverged_step")
            ));
        }
        r.ints("attempts/step", &a_step, &i64s(f, "attempts/step"));
        r.ints(
            "attempts/converged",
            &a_conv,
            &i64s(f, "attempts/converged"),
        );
        r.ints(
            "attempts/nb_iterations",
            &a_its,
            &i64s(f, "attempts/nb_iterations"),
        );
        r.bits("attempts/error", &a_err, &f64s(f, "attempts/error"));
        r.bits(
            "attempts/top_reaction_x",
            &a_rx,
            &f64s(f, "attempts/top_reaction_x"),
        );
        r.bits(
            "attempts/top_reaction_y",
            &a_ry,
            &f64s(f, "attempts/top_reaction_y"),
        );
        r.bits(
            "standalone/top_reaction",
            &sa,
            &f64s(f, "standalone/top_reaction"),
        );
        for (key, ours) in [
            ("displacement", model.smm.displacement().unwrap().as_slice()),
            (
                "internal_force",
                model.smm.internal_force().unwrap().as_slice(),
            ),
        ] {
            r.bits(key, ours, &f64s(f, key));
        }
        r.ints(
            "blocked_dofs",
            &bools(model.smm.blocked_dofs().unwrap().as_slice()),
            &i64s(f, "blocked_dofs"),
        );
        let k = model.smm.dof_manager().matrix("K").unwrap();
        let (rows, cols, vals) = k.coo();
        r.ints("K/rows", rows, &i64s(f, "K/rows"));
        r.ints("K/cols", cols, &i64s(f, "K/cols"));
        r.bits("K/values", vals, &f64s(f, "K/values"));
        {
            let m = mesh.read().unwrap();
            r.bits("mesh/nodes", m.nodes().as_slice(), &f64s(f, "mesh/nodes"));
            for t in param(f, "mesh_types").as_array().unwrap() {
                let t = t.as_str().unwrap();
                let ours: Vec<i64> = m
                    .connectivity(cohesive_type(t), GhostType::NotGhost)
                    .map(|c| c.as_slice().iter().map(|&x| i64::from(x)).collect())
                    .unwrap_or_default();
                let key = format!("mesh/connectivity/{t}");
                r.ints(&key, &ours, &i64s(f, &key));
            }
        }
        compare_internals(
            f,
            model.cohesive_material("cohesive").unwrap(),
            "cohesive",
            &mut r,
        );
        assert_all_compared(f, &r.names, &[]);
    }
    let k_values = model
        .smm
        .dof_manager()
        .matrix("K")
        .unwrap()
        .coo()
        .2
        .to_vec();
    V57Run {
        report: r,
        iterations: a_its,
        not_converged,
        failed_step,
        standalone_history,
        contact_steps,
        reverse_steps,
        k_values,
        errors: a_err,
    }
}

/// The adversarial implicit cases (`adv_v57_*`, x86_64
/// oracle): bitwise under the upstream switch set (contact
/// reversal with the contact branch active; standalone overshoot between
/// steps, forced Newton failure and retry). Corrected defaults: every step
/// converges (the forced single-iteration attempt aside), the contact
/// branch is reached, and the standalone evaluation is a trial (the
/// committed `δ_max` is unchanged by it, UD-245).
#[test]
fn adversarial_v57_implicit_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let expected: Vec<String> = V57_FAMILY.iter().map(|s| (*s).to_owned()).collect();
    for case in family_cases("adversarial_v57_implicit_cases", &expected) {
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        let c = replay_v57_adversarial(&f, Switches::UPSTREAM);
        if UD1160_CASES.contains(&case.as_str()) {
            let u = replay_v57_adversarial(&f, WITHOUT_FAILED_SECANT);
            assert_discriminates_ud1160(
                &case,
                (&u.iterations, &i64s(&f, "attempts/nb_iterations")),
                (&u.errors, &f64s(&f, "attempts/error")),
                (&u.k_values, &f64s(&f, "K/values")),
            );
        }
        total += c.report.compared;
        eprintln!(
            "{case} (upstream switch set): {} values compared, {} mismatching; {} attempts, {} iterations, contact at {} converged steps",
            c.report.compared,
            c.report.errors.len(),
            c.iterations.len(),
            c.iterations.iter().sum::<i64>(),
            c.contact_steps.len()
        );
        for e in c.report.errors.iter().take(12) {
            eprintln!("    {e}");
        }
        if !c.report.errors.is_empty() {
            failures.push(case.clone());
        }
        let d = replay_v57_adversarial(&f, Switches::DEFAULT);
        assert_eq!(d.failed_step, -1, "{case}: the default run converges");
        let fail_at = param(&f, "fail_at").as_i64().unwrap();
        assert!(
            d.not_converged.iter().all(|&s| s == fail_at),
            "{case}: default non-converged attempts {:?}",
            d.not_converged
        );
        if case.contains("contact_reversal") {
            assert!(
                !d.contact_steps.is_empty() && !c.contact_steps.is_empty(),
                "{case}: the contact branch is reached"
            );
        }
        if param(&f, "standalone_at").as_i64().unwrap() >= 0 {
            let (before, after) = &d.standalone_history;
            assert!(!before.is_empty(), "{case}: default history");
            assert_eq!(
                before, after,
                "{case}: the standalone evaluation is a trial"
            );
        }
        eprintln!(
            "{case} (default): {} attempts, {} iterations (upstream {}), contact at {} converged steps",
            d.iterations.len(),
            d.iterations.iter().sum::<i64>(),
            c.iterations.iter().sum::<i64>(),
            d.contact_steps.len()
        );
    }
    assert!(failures.is_empty(), "{failures:?}");
    assert_family_total(
        "adversarial_v57_implicit_cases",
        total,
        V57_FAMILY_VALUES,
        V57_FAMILY_VALUES,
        0,
    );
}

// ---------------------------------------------------------------------------
// The va3_* oracle cases
// (oracle/probes/cohesive/cohesive_probe.cc, x86_64, Eigen cache sizes
// pinned per D-050). Replayed bitwise under the exact rule; each also
// asserts what it exercises.
// ---------------------------------------------------------------------------

/// The nodal arrays upstream `onNodesAdded` copies (`<prefix>displacement`,
/// …, `<prefix>mass`), as recorded by the probe's `record_nodal_state`.
fn compare_nodal_state(
    f: &Fixture,
    model: &SolidMechanicsModelCohesive,
    prefix: &str,
    r: &mut Report,
) {
    let fam = model
        .smm
        .dof_manager()
        .family(akantu_solid::model::DOF_ID)
        .unwrap();
    let prev_g = fam.previous.as_ref().map(|a| a.read().unwrap());
    let inc_g = fam.increment.as_ref().map(|a| a.read().unwrap());
    r.bits(
        &format!("{prefix}displacement"),
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, &format!("{prefix}displacement")),
    );
    r.bits(
        &format!("{prefix}velocity"),
        model.smm.velocity().unwrap().as_slice(),
        &f64s(f, &format!("{prefix}velocity")),
    );
    r.bits(
        &format!("{prefix}acceleration"),
        model.smm.acceleration().unwrap().as_slice(),
        &f64s(f, &format!("{prefix}acceleration")),
    );
    r.bits(
        &format!("{prefix}previous_displacement"),
        prev_g.as_deref().map_or(&[][..], |a| a.as_slice()),
        &f64s(f, &format!("{prefix}previous_displacement")),
    );
    r.bits(
        &format!("{prefix}increment"),
        inc_g.as_deref().map_or(&[][..], |a| a.as_slice()),
        &f64s(f, &format!("{prefix}increment")),
    );
    r.bits(
        &format!("{prefix}solution"),
        fam.solution.as_slice(),
        &f64s(f, &format!("{prefix}solution")),
    );
    r.ints(
        &format!("{prefix}blocked_dofs"),
        &bools(model.smm.blocked_dofs().unwrap().as_slice()),
        &i64s(f, &format!("{prefix}blocked_dofs")),
    );
    r.bits(
        &format!("{prefix}mass"),
        model.smm.mass().unwrap().as_slice(),
        &f64s(f, &format!("{prefix}mass")),
    );
}

/// `<prefix>check_facets/<type>` and `<prefix>insertion_facets/<type>`.
fn compare_flags(f: &Fixture, model: &SolidMechanicsModelCohesive, prefix: &str, r: &mut Report) {
    for key in f.quantity_names(&format!("{prefix}check_facets/*")) {
        let ty = cohesive_type(&key[format!("{prefix}check_facets/").len()..]);
        let ours = model
            .ext
            .inserter
            .check_facets()
            .get(ty, GhostType::NotGhost)
            .map(|a| bools(a.as_slice()))
            .unwrap_or_default();
        r.ints(key, &ours, &i64s(f, key));
    }
    for key in f.quantity_names(&format!("{prefix}insertion_facets/*")) {
        let ty = cohesive_type(&key[format!("{prefix}insertion_facets/").len()..]);
        let ours = model
            .ext
            .inserter
            .insertion_facets()
            .get(ty, GhostType::NotGhost)
            .map(|a| bools(a.as_slice()))
            .unwrap_or_default();
        r.ints(key, &ours, &i64s(f, key));
    }
}

fn idx_vec(
    a: Option<impl std::ops::Deref<Target = akantu_core::Array<akantu_core::Idx>>>,
) -> Vec<i64> {
    a.map(|a| a.as_slice().iter().map(|&x| i64::from(x)).collect())
        .unwrap_or_default()
}

/// Replay of `va3_facets_only_triangle_3`: `insert_facets_only` (upstream
/// `insertElements(true)`) during an explicit run.
fn replay_va3_facets_only(f: &Fixture) -> Report {
    let mut r = Report::default();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(
        param(f, "random_seed").as_i64().unwrap(),
    );
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    model
        .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    let stable = model.stable_time_step().unwrap();
    let dt = stable * 0.01;
    model.set_time_step(dt, None).unwrap();
    r.bits("time_step", &[stable, dt], &f64s(f, "time_step"));
    let sigma_c = common::real_param(&model, "insertion", "sigma_c");
    let e = common::real_param(&model, "body", "E");
    let nu = common::real_param(&model, "body", "nu");
    let mut strain = vec![-nu * (1. + nu), 0., 0., (1. - nu) * (1. + nu)];
    for x in &mut strain {
        *x *= sigma_c / e;
    }
    let init_factor = param(f, "init_factor").as_f64().unwrap();
    let inc_factor = param(f, "inc_factor").as_f64().unwrap();
    let init: Vec<Real> = strain.iter().map(|s| init_factor * s).collect();
    {
        let nodes = mesh.read().unwrap().nodes().as_slice().to_vec();
        let mut u = model.smm.displacement_mut().unwrap();
        for (x, ui) in nodes.chunks(2).zip(u.as_mut_slice().chunks_mut(2)) {
            for i in 0..2 {
                let mut acc = 0.0;
                for k in 0..2 {
                    acc += init[i + 2 * k] * x[k];
                }
                ui[i] = acc;
            }
        }
    }
    let functor = StrainIncrement {
        strain: strain
            .iter()
            .map(|s| 1. / 300. * (inc_factor * s))
            .collect(),
        dim: 2,
        dir: 1,
    };
    let (mut ek, mut ep) = (Vec::new(), Vec::new());
    let before = param(f, "steps_before").as_u64().unwrap() as usize;
    let after = param(f, "steps_after").as_u64().unwrap() as usize;
    for _ in 0..before {
        model.smm.apply_dirichlet_bc(&functor, "loading").unwrap();
        model.smm.apply_dirichlet_bc(&functor, "fixed").unwrap();
        model.solve_step(None).unwrap();
        ek.push(model.energy("kinetic").unwrap());
        ep.push(model.energy("potential").unwrap());
    }
    {
        let chk = model
            .ext
            .inserter
            .check_facets()
            .get(ElementType::Segment2, GhostType::NotGhost)
            .unwrap()
            .as_slice()
            .to_vec();
        model
            .ext
            .inserter
            .insertion_facets_mut()
            .get_mut(ElementType::Segment2, GhostType::NotGhost)
            .unwrap()
            .as_mut_slice()
            .copy_from_slice(&chk);
    }
    compare_flags(f, &model, "before/", &mut r);
    r.bits(
        "before/displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, "before/displacement"),
    );
    let res = model.insert_facets_only().unwrap();
    assert!(
        !res.doubled_facets.is_empty() && !res.doubled_nodes.is_empty(),
        "va3_facets_only: facets and nodes doubled"
    );
    r.ints(
        "facets_only/returned",
        &[res.new_elements.len() as i64],
        &i64s(f, "facets_only/returned"),
    );
    r.ints(
        "facets_only/nb_cohesive",
        &[mesh
            .read()
            .unwrap()
            .nb_element(ElementType::Cohesive2d4, GhostType::NotGhost) as i64],
        &i64s(f, "facets_only/nb_cohesive"),
    );
    compare_flags(f, &model, "after/", &mut r);
    compare_nodal_state(f, &model, "after/", &mut r);
    compare_topology(f, &model, &mut r);
    let digests = param(f, "step_digests").as_array().unwrap();
    let mut first_digest_mismatch = None;
    for k in 0..after {
        model.smm.apply_dirichlet_bc(&functor, "loading").unwrap();
        model.smm.apply_dirichlet_bc(&functor, "fixed").unwrap();
        model.solve_step(None).unwrap();
        ek.push(model.energy("kinetic").unwrap());
        ep.push(model.energy("potential").unwrap());
        let d = digest(&[
            model.smm.displacement().unwrap().as_slice(),
            model.smm.velocity().unwrap().as_slice(),
            model.smm.acceleration().unwrap().as_slice(),
        ]);
        if first_digest_mismatch.is_none() && digests.get(k).and_then(|v| v.as_str()) != Some(&d) {
            first_digest_mismatch = Some(k);
        }
    }
    r.compared += digests.len();
    if digests.len() != after {
        r.errors
            .push(format!("{} step digests, expected {after}", digests.len()));
    }
    if let Some(k) = first_digest_mismatch {
        r.errors.push(format!(
            "step digest differs from step {k} after the insertion"
        ));
    }
    r.bits(
        "steps/energy/kinetic",
        &ek,
        &f64s(f, "steps/energy/kinetic"),
    );
    r.bits(
        "steps/energy/potential",
        &ep,
        &f64s(f, "steps/energy/potential"),
    );
    compare_nodal_state(f, &model, "final/", &mut r);
    r.bits(
        "final/internal_force",
        model.smm.internal_force().unwrap().as_slice(),
        &f64s(f, "final/internal_force"),
    );
    assert_all_compared(f, &r.names, &[]);
    r
}

/// Upstream `cohesive_extrinsic_ig_tg` `Velocity` functor (displacement
/// part; the velocity of the group's nodes is set by the caller).
struct IgTgVelocity {
    axis: usize,
    disp: Real,
}

impl akantu_model::boundary_condition::DirichletFunctor for IgTgVelocity {
    fn apply(
        &self,
        _node: akantu_core::Idx,
        _flags: &mut [bool],
        primal: &mut [Real],
        coord: &[Real],
    ) -> akantu_core::Result<()> {
        let sign = if coord[self.axis].is_sign_negative() {
            -1.
        } else {
            1.
        };
        primal[self.axis] += sign * self.disp;
        Ok(())
    }
}

/// `model.getVelocity()(node, axis) = sign · vel` of the functor, for every
/// node of `group`.
fn set_group_velocity(
    model: &mut SolidMechanicsModelCohesive,
    group: &str,
    axis: usize,
    vel: Real,
) {
    let (nodes, x) = {
        let m = model.smm.physics.base.mesh.read().unwrap();
        let nodes = m.groups().element_group(group).unwrap().nodes().to_vec();
        (nodes, m.nodes().as_slice().to_vec())
    };
    let mut v_g = model.smm.velocity_mut().unwrap();
    let v = v_g.as_mut_slice();
    for n in nodes {
        let n = n as usize;
        let sign = if x[2 * n + axis].is_sign_negative() {
            -1.
        } else {
            1.
        };
        v[2 * n + axis] = sign * vel;
    }
}

/// The rules of an ig_tg case: the parameter `rules` (`[side 1, side 2,
/// law]`, adversarial variants) or the example's.
fn ig_tg_rules(f: &Fixture) -> akantu_cohesive::selector::MaterialCohesiveRules {
    let example = [
        ["btop", "bbottom", "tg_cohesive"],
        ["btop", "btop", "ig_cohesive"],
        ["bbottom", "bbottom", "ig_cohesive"],
    ]
    .map(|r| r.map(str::to_owned).to_vec());
    let rules: Vec<Vec<String>> = match param(f, "rules").as_array() {
        Some(list) => list
            .iter()
            .map(|e| {
                e.as_array()
                    .unwrap()
                    .iter()
                    .map(|x| x.as_str().unwrap().to_owned())
                    .collect()
            })
            .collect(),
        None => example.to_vec(),
    };
    rules
        .into_iter()
        .map(|r| ((r[0].clone(), r[1].clone()), r[2].clone()))
        .collect()
}

/// The upstream example `cohesive_extrinsic_ig_tg` up to `assembleMassLumped`
/// (rules selector → `MeshDataMaterialSelector(physical_names)` → default
/// selectors; `cohesive_zones` from the material file or
/// `add_physical_volume("btop")`), the explicit time step and the boundary
/// flags and initial velocity of the example. Returns the model, its mesh
/// and `(stable time step, time step)`.
fn ig_tg_model(
    f: &Fixture,
    compat: akantu_cohesive::CohesiveUpstreamCompat,
) -> (
    SolidMechanicsModelCohesive,
    akantu_mesh::SharedMesh,
    Real,
    Real,
) {
    use akantu_cohesive::selector::MaterialCohesiveRulesSelector;
    use akantu_model::constitutive_law::{ElementDataSelector, LawIndexSelector, SelectorChain};
    let zone_btop = param(f, "zone_btop").as_bool().unwrap_or(false);
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), 2);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(
        param(f, "random_seed").as_i64().unwrap(),
    );
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    model.ext.compat = compat;
    let sel = MaterialCohesiveRulesSelector {
        rules: ig_tg_rules(f),
        mesh_data_id: "physical_names".into(),
        default: model.default_cohesive_selector(),
    };
    // upstream: rules → MeshDataMaterialSelector(physical_names) → the
    // model's DefaultMaterialCohesiveSelector → DefaultMaterialSelector
    model.set_material_selector_chain(SelectorChain {
        selectors: vec![
            Box::new(sel),
            Box::new(ElementDataSelector::new("physical_names")),
            Box::new(model.default_cohesive_selector()),
            Box::new(LawIndexSelector),
        ],
        fallback_value: 0,
    });
    if zone_btop {
        model.ext.inserter.add_physical_volume("btop");
    }
    model
        .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    let stable = model.stable_time_step().unwrap();
    let dt = stable * 0.05;
    model.set_time_step(dt, None).unwrap();
    model.smm.assemble_mass_lumped().unwrap();
    (model, mesh, stable, dt)
}

/// The example's boundary flags and initial velocity `v = 0.1 x`.
fn ig_tg_boundary(model: &mut SolidMechanicsModelCohesive, mesh: &akantu_mesh::SharedMesh) {
    for g in ["top", "bottom"] {
        model.smm.apply_dirichlet_bc(&FlagOnly(1), g).unwrap();
    }
    for g in ["left", "right"] {
        model.smm.apply_dirichlet_bc(&FlagOnly(0), g).unwrap();
    }
    let loading_rate = 0.1;
    let x = mesh.read().unwrap().nodes().as_slice().to_vec();
    let mut v_g = model.smm.velocity_mut().unwrap();
    let v = v_g.as_mut_slice();
    for (vi, xi) in v.iter_mut().zip(&x) {
        *vi = loading_rate * xi;
    }
}

/// One loading step of the example (velocity functors on the four sides).
fn ig_tg_apply_velocity(model: &mut SolidMechanicsModelCohesive, dt: Real) {
    let vi = 0.1 * 2. * 0.5;
    let vely = IgTgVelocity {
        axis: 1,
        disp: vi * dt,
    };
    let velx = IgTgVelocity {
        axis: 0,
        disp: vi * dt,
    };
    model.smm.apply_dirichlet_bc(&vely, "top").unwrap();
    set_group_velocity(model, "top", 1, vi);
    model.smm.apply_dirichlet_bc(&vely, "bottom").unwrap();
    set_group_velocity(model, "bottom", 1, vi);
    model.smm.apply_dirichlet_bc(&velx, "left").unwrap();
    set_group_velocity(model, "left", 0, vi);
    model.smm.apply_dirichlet_bc(&velx, "right").unwrap();
    set_group_velocity(model, "right", 0, vi);
}

/// Replay of `va3_ig_tg_rules_zones` / `va3_ig_tg_zone_btop` and the rules
/// variants `v92_ig_tg_rules_*`: the upstream example with
/// `MaterialCohesiveRulesSelector` and `cohesive_zones` (or
/// `add_physical_volume`).
fn replay_va3_ig_tg(f: &Fixture) -> (Report, usize, Vec<(String, String)>) {
    let mut r = Report::default();
    let max_steps = param(f, "max_steps").as_u64().unwrap() as usize;
    let (mut model, mesh, stable, dt) =
        ig_tg_model(f, akantu_cohesive::CohesiveUpstreamCompat::default());
    let neighbours = facet_neighbour_names(&model);
    r.bits("time_step", &[stable, dt], &f64s(f, "time_step"));
    ig_tg_boundary(&mut model, &mesh);
    for key in f.quantity_names("init/facet_material/*") {
        let ty = cohesive_type(&key["init/facet_material/".len()..]);
        let ours = idx_vec(model.ext.facet_material.get(ty, GhostType::NotGhost).ok());
        r.ints(key, &ours, &i64s(f, key));
    }
    compare_flags(f, &model, "init/", &mut r);
    for key in f.quantity_names("init/material_index/*") {
        let ty = cohesive_type(&key["init/material_index/".len()..]);
        let ours = idx_vec(
            model
                .smm
                .physics
                .materials
                .law_index_map()
                .get(ty, GhostType::NotGhost)
                .ok(),
        );
        r.ints(key, &ours, &i64s(f, key));
    }
    let digests = param(f, "step_digests").as_array().unwrap();
    let mut first_digest_mismatch = None;
    let (mut ins, mut ncoh) = (Vec::new(), Vec::new());
    let (mut ek, mut ep, mut ed, mut er, mut ec) = (vec![], vec![], vec![], vec![], vec![]);
    let mut first = None;
    for s in 1..=max_steps {
        ig_tg_apply_velocity(&mut model, dt);
        let n = model.check_cohesive_stress().unwrap();
        ins.push(n as i64);
        ncoh.push(
            mesh.read()
                .unwrap()
                .nb_element(ElementType::Cohesive2d4, GhostType::NotGhost) as i64,
        );
        if n > 0 && first.is_none() {
            first = Some(s);
            compare_nodal_state(f, &model, "first_insertion/", &mut r);
        }
        model.solve_step(None).unwrap();
        ek.push(model.energy("kinetic").unwrap());
        ep.push(model.energy("potential").unwrap());
        ed.push(model.energy("dissipated").unwrap());
        er.push(model.energy("reversible").unwrap());
        ec.push(model.energy("cohesive contact").unwrap());
        if s % 50 == 0 {
            let d = digest(&[
                model.smm.displacement().unwrap().as_slice(),
                model.smm.velocity().unwrap().as_slice(),
                model.smm.acceleration().unwrap().as_slice(),
            ]);
            if first_digest_mismatch.is_none()
                && digests.get(s / 50 - 1).and_then(|v| v.as_str()) != Some(&d)
            {
                first_digest_mismatch = Some(s);
            }
        }
    }
    if first.map(|s| s as i64) != param(f, "first_insertion_step").as_i64() {
        r.errors.push(format!(
            "first insertion at step {first:?}, oracle {}",
            param(f, "first_insertion_step")
        ));
    }
    r.compared += digests.len();
    if let Some(s) = first_digest_mismatch {
        r.errors.push(format!("step digest differs at step {s}"));
    }
    r.ints("steps/inserted", &ins, &i64s(f, "steps/inserted"));
    r.ints("steps/nb_cohesive", &ncoh, &i64s(f, "steps/nb_cohesive"));
    r.bits(
        "steps/energy/kinetic",
        &ek,
        &f64s(f, "steps/energy/kinetic"),
    );
    r.bits(
        "steps/energy/potential",
        &ep,
        &f64s(f, "steps/energy/potential"),
    );
    r.bits(
        "steps/energy/dissipated",
        &ed,
        &f64s(f, "steps/energy/dissipated"),
    );
    r.bits(
        "steps/energy/reversible",
        &er,
        &f64s(f, "steps/energy/reversible"),
    );
    r.bits(
        "steps/energy/cohesive_contact",
        &ec,
        &f64s(f, "steps/energy/cohesive_contact"),
    );
    compare_nodal_state(f, &model, "final/", &mut r);
    r.bits(
        "final/internal_force",
        model.smm.internal_force().unwrap().as_slice(),
        &f64s(f, "final/internal_force"),
    );
    compare_topology(f, &model, &mut r);
    compare_flags(f, &model, "final/", &mut r);
    for key in f.quantity_names("final/facet_material/*") {
        let ty = cohesive_type(&key["final/facet_material/".len()..]);
        let ours = idx_vec(model.ext.facet_material.get(ty, GhostType::NotGhost).ok());
        r.ints(key, &ours, &i64s(f, key));
    }
    for key in f.quantity_names("final/material_index/*") {
        let ty = cohesive_type(&key["final/material_index/".len()..]);
        let ours = idx_vec(
            model
                .smm
                .physics
                .materials
                .law_index_map()
                .get(ty, GhostType::NotGhost)
                .ok(),
        );
        r.ints(key, &ours, &i64s(f, key));
    }
    for law in ["tg_cohesive", "ig_cohesive"] {
        compare_internals(f, model.cohesive_material(law).unwrap(), law, &mut r);
    }
    assert_all_compared(f, &r.names, &[]);
    let total: usize = ins.iter().sum::<i64>() as usize;
    (r, total, neighbours)
}

/// `(physical name of neighbour 1, of neighbour 2)` of every `_segment_2`
/// facet in `element_to_subelement` order (a boundary facet: `(a, a)`, as
/// upstream's rules selector looks it up).
fn facet_neighbour_names(model: &SolidMechanicsModelCohesive) -> Vec<(String, String)> {
    let m = model.smm.physics.base.mesh.read().unwrap();
    let names = m.data().strings("physical_names").unwrap();
    let fm = m.mesh_facets().unwrap();
    let e2s = fm
        .data()
        .element_lists(akantu_mesh::utils::ELEMENT_TO_SUBELEMENT)
        .unwrap();
    let name = |e: akantu_core::Element| names.element(e).unwrap()[0].clone();
    (0..fm.nb_element(ElementType::Segment2, GhostType::NotGhost))
        .map(|k| {
            let facet =
                akantu_core::Element::try_new(ElementType::Segment2, k, GhostType::NotGhost)
                    .unwrap();
            let row = &e2s.element(facet).unwrap()[0];
            let n1 = name(row[0]);
            let n2 = match row.get(1) {
                Some(e) if !e.is_null() => name(*e),
                _ => n1.clone(),
            };
            (n1, n2)
        })
        .collect()
}

/// The prescribed path of `va3_friction_prescribed_quadrangle_4` (the
/// probe's `ramp`, same arithmetic): `(dx, dy)` per step.
fn va3_friction_path() -> Vec<Vec<Real>> {
    let mut path: Vec<Vec<Real>> = Vec::new();
    let mut ramp = |x1: Real, y1: Real, n: u32| {
        let (x0, y0) = path.last().map_or((0., 0.), |p| (p[0], p[1]));
        for k in 1..=n {
            let f = Real::from(k) / Real::from(n);
            path.push(vec![x0 + (x1 - x0) * f, y0 + (y1 - y0) * f]);
        }
    };
    ramp(0., 3e-6, 6);
    ramp(1e-7, 3e-6, 1);
    ramp(1e-7, -2e-6, 5);
    ramp(2e-6, -2e-6, 19);
    ramp(5e-7, -2e-6, 15);
    ramp(1.5e-6, -2e-6, 10);
    ramp(1.5e-6, 1.5e-5, 10);
    ramp(1.5e-6, -1e-6, 10);
    ramp(4e-6, -1e-6, 10);
    path
}

/// The prescribed path of `cmf_friction_prescribed_tetrahedron_4` (the
/// probe's `ramp`, same arithmetic): `(dx, dy, dz)` per step.
fn cmf_friction_path() -> Vec<Vec<Real>> {
    let mut path: Vec<Vec<Real>> = Vec::new();
    let mut ramp = |x1: Real, y1: Real, z1: Real, n: u32| {
        let a = path.last().cloned().unwrap_or_else(|| vec![0.; 3]);
        for k in 1..=n {
            let f = Real::from(k) / Real::from(n);
            path.push(vec![
                a[0] + (x1 - a[0]) * f,
                a[1] + (y1 - a[1]) * f,
                a[2] + (z1 - a[2]) * f,
            ]);
        }
    };
    ramp(0., 3e-6, 0., 6);
    ramp(1e-7, 3e-6, 0., 1);
    ramp(1e-7, -2e-6, 0., 5);
    ramp(2e-6, -2e-6, 0., 19);
    ramp(2e-6, -2e-6, 1.5e-6, 12);
    ramp(6e-7, -2e-6, 1.5e-6, 14);
    ramp(6e-7, -1.2e-6, 4e-7, 8);
    ramp(1.6e-6, -1.2e-6, 1.2e-6, 10);
    ramp(1.6e-6, 1.5e-5, 1.2e-6, 10);
    ramp(1.6e-6, -1e-6, 1.2e-6, 10);
    ramp(4e-6, -1e-6, 3e-6, 10);
    path
}

/// What the friction replay saw at point 0: steps in contact with a
/// friction force, forward stick (0 < τ < τ_max), forward slip (τ = τ_max),
/// reverse sliding (τ < 0: the friction force against the tangential
/// opening; upstream's residual sliding `|Δt| − |τ|/k_f` is wrong there,
/// UD-249, and the reverse branch chatters below τ_max), residual sliding
/// changes; the per-step state of point 0 (opening, friction force,
/// residual sliding, contact traction) for the closed-form check of the
/// default run.
#[derive(Debug, Default)]
struct FrictionStats {
    contact: usize,
    stick: usize,
    slip_forward: usize,
    reverse: usize,
    sliding_changes: usize,
    steps: Vec<FrictionStep>,
}

/// State of point 0 after one step of the friction replay.
#[derive(Debug, Clone)]
struct FrictionStep {
    opening: Vec<Real>,
    friction_force: Vec<Real>,
    residual_sliding: Real,
    contact_traction: Vec<Real>,
}

/// Default run of a prescribed-motion friction case (**UD-249** corrected
/// update) against the play operator on the norm of the tangential opening,
/// `s = clamp(s_prev, x − r, x + r)`, `τ = k_f (x − s)`, `r = τ_max/k_f`,
/// `τ_max = μ |t_contact|` (μ 0.3, k_f 1e12 in both cases), at every
/// penetrating step (the residual sliding is kept through the open steps,
/// as the law does; in 3-D the scalar law follows any direction of `Δt`).
/// Returns the worst deviation relative to `τ_max` (force components and
/// `k_f·s`) and the number of steps checked.
fn friction_play_operator(steps: &[FrictionStep]) -> (Real, usize) {
    let (mu, kf) = (0.3, 1e12);
    let mut s_cf: Real = 0.0;
    let mut worst: Real = 0.0;
    let mut checked = 0;
    for st in steps {
        let dim = st.opening.len();
        let ct = st
            .contact_traction
            .iter()
            .map(|c| c * c)
            .sum::<Real>()
            .sqrt();
        if ct == 0.0 {
            continue;
        }
        let tau_max = mu * ct;
        let x = akantu_cohesive::vecops::norm_fixed(&st.opening, dim);
        let r = tau_max / kf;
        s_cf = s_cf.max(x - r).min(x + r);
        let tau = kf * (x - s_cf);
        let mut e = (st.residual_sliding - s_cf).abs() * kf;
        for i in 0..dim {
            e = e.nan_max((st.friction_force[i] - tau * st.opening[i] / x).abs());
        }
        worst = worst.nan_max(e / tau_max);
        checked += 1;
    }
    (worst, checked)
}

/// Replay of a prescribed-motion friction case
/// (`va3_friction_prescribed_quadrangle_4`, 2-D; `cmf_friction_prescribed_
/// tetrahedron_4`, 3-D): insertion at a uniform tension of 2 σc, then the
/// upper half moved rigidly along `path` with every DOF blocked; `compat`:
/// the **UD-249** switch `friction_residual_sliding_abs` (upstream's update,
/// the bitwise replay), otherwise the corrected default (only the steps
/// from the first reverse sliding on can differ).
fn replay_prescribed_friction(
    f: &Fixture,
    compat: bool,
    dim: usize,
    ct_type: ElementType,
    path: &[Vec<Real>],
) -> (Report, FrictionStats) {
    let mut r = Report::default();
    let mesh = common::read_mesh(&f.input_path("mesh").unwrap(), dim);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    akantu_core::random::RandomGenerator::<akantu_core::random::IdxSlot>::seed(
        param(f, "random_seed").as_i64().unwrap(),
    );
    let mut model = SolidMechanicsModelCohesive::with_parser(
        mesh.clone(),
        None,
        "solid_mechanics_model_cohesive",
        parser,
    )
    .unwrap();
    model.ext.compat.friction_residual_sliding_abs = compat;
    model
        .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass), true)
        .unwrap();
    let stable = model.stable_time_step().unwrap();
    let dt = stable * 0.05;
    model.set_time_step(dt, None).unwrap();
    r.bits("time_step", &[stable, dt], &f64s(f, "time_step"));
    let x = mesh.read().unwrap().nodes().as_slice().to_vec();
    {
        let mut u_g = model.smm.displacement_mut().unwrap();
        let u = u_g.as_mut_slice();
        for n in 0..x.len() / dim {
            for i in 0..dim {
                u[dim * n + i] = if i == 1 {
                    2. * 1e6 / 1e9 * x[dim * n + 1]
                } else {
                    0.
                };
            }
        }
    }
    model.assemble_internal_forces().unwrap();
    let inserted = model.check_cohesive_stress().unwrap();
    r.ints(
        "insertion/inserted",
        &[inserted as i64],
        &i64s(f, "insertion/inserted"),
    );
    let top: Vec<bool> = {
        let m = mesh.read().unwrap();
        let x_g = m.nodes();
        let x = x_g.as_slice();
        let mut top = vec![false; m.nb_nodes()];
        for ty in m.element_types(
            akantu_core::TypeFilter::new()
                .dim(dim)
                .kind(akantu_core::ElementKind::Regular),
        ) {
            let conn = m.connectivity(ty, GhostType::NotGhost).unwrap();
            for row in conn.as_slice().chunks(conn.nb_component()) {
                let mut yb = 0.0;
                for &n in row {
                    yb += x[dim * n as usize + 1];
                }
                if yb > 0. {
                    for &n in row {
                        top[n as usize] = true;
                    }
                }
            }
        }
        top
    };
    model.smm.blocked_dofs_mut().unwrap().fill(true);
    let (mut ed, mut er, mut ec) = (vec![], vec![], vec![]);
    let (mut tr, mut ctr, mut ff, mut rs, mut op, mut dmg, mut dmx) =
        (vec![], vec![], vec![], vec![], vec![], vec![], vec![]);
    let mut stats = FrictionStats::default();
    let (mu, penalty) = (0.3, 1e12);
    let mut prev_rs = 0.0;
    for d in path {
        {
            let mut u_g = model.smm.displacement_mut().unwrap();
            let u = u_g.as_mut_slice();
            for (n, &t) in top.iter().enumerate() {
                for i in 0..dim {
                    u[dim * n + i] = if t { d[i] } else { 0. };
                }
            }
        }
        model.solve_step(None).unwrap();
        ed.push(model.energy("dissipated").unwrap());
        er.push(model.energy("reversible").unwrap());
        ec.push(model.energy("cohesive contact").unwrap());
        let mat = model.cohesive_material("insertion").unwrap();
        let q0 = |name: &str, nc: usize| -> Vec<Real> {
            mat.array(name, ct_type, GhostType::NotGhost)
                .unwrap()
                .as_slice()[..nc]
                .to_vec()
        };
        let (t, c, fr, s) = (
            q0("tractions", dim),
            q0("contact_tractions", dim),
            q0("friction_force", dim),
            q0("residual_sliding", 1),
        );
        let o = q0("opening", dim);
        let co = q0("contact_opening", dim);
        let norm = |v: &[Real]| v.iter().map(|a| a * a).sum::<Real>().sqrt();
        let (dn, tau) = (norm(&co), norm(&fr));
        if dn > 0. && tau > 0. {
            stats.contact += 1;
            let tau_max = mu * penalty * dn;
            // signed: friction force along the tangential opening or against
            if fr.iter().zip(&o).map(|(a, b)| a * b).sum::<Real>() < 0. {
                stats.reverse += 1;
            } else if (tau - tau_max).abs() <= 1e-12 * tau_max {
                stats.slip_forward += 1;
            } else {
                stats.stick += 1;
            }
        }
        if s[0] != prev_rs {
            stats.sliding_changes += 1;
        }
        prev_rs = s[0];
        stats.steps.push(FrictionStep {
            opening: o.clone(),
            friction_force: fr.clone(),
            residual_sliding: s[0],
            contact_traction: c.clone(),
        });
        tr.extend(t);
        ctr.extend(c);
        ff.extend(fr);
        rs.extend(s);
        op.extend(o);
        dmg.extend(q0("damage", 1));
        dmx.extend(q0("delta max", 1));
    }
    r.bits(
        "steps/energy/dissipated",
        &ed,
        &f64s(f, "steps/energy/dissipated"),
    );
    r.bits(
        "steps/energy/reversible",
        &er,
        &f64s(f, "steps/energy/reversible"),
    );
    r.bits(
        "steps/energy/cohesive_contact",
        &ec,
        &f64s(f, "steps/energy/cohesive_contact"),
    );
    r.bits("steps/q0/tractions", &tr, &f64s(f, "steps/q0/tractions"));
    r.bits(
        "steps/q0/contact_tractions",
        &ctr,
        &f64s(f, "steps/q0/contact_tractions"),
    );
    r.bits(
        "steps/q0/friction_force",
        &ff,
        &f64s(f, "steps/q0/friction_force"),
    );
    r.bits(
        "steps/q0/residual_sliding",
        &rs,
        &f64s(f, "steps/q0/residual_sliding"),
    );
    r.bits("steps/q0/opening", &op, &f64s(f, "steps/q0/opening"));
    r.bits("steps/q0/damage", &dmg, &f64s(f, "steps/q0/damage"));
    r.bits("steps/q0/delta_max", &dmx, &f64s(f, "steps/q0/delta_max"));
    r.bits(
        "displacement",
        model.smm.displacement().unwrap().as_slice(),
        &f64s(f, "displacement"),
    );
    r.bits(
        "internal_force",
        model.smm.internal_force().unwrap().as_slice(),
        &f64s(f, "internal_force"),
    );
    compare_topology(f, &model, &mut r);
    compare_internals(
        f,
        model.cohesive_material("insertion").unwrap(),
        "insertion",
        &mut r,
    );
    assert_all_compared(f, &r.names, &[]);
    (r, stats)
}

/// Replay of `va3_friction_prescribed_quadrangle_4` (see
/// [`replay_prescribed_friction`]).
fn replay_va3_friction(f: &Fixture, compat: bool) -> (Report, FrictionStats) {
    replay_prescribed_friction(f, compat, 2, ElementType::Cohesive2d4, &va3_friction_path())
}

/// `va3_oracle_cases`: facets-only 4,188 + friction 7,939 +
/// ig_tg rules/zones 10,970 + zone btop 9,723 values.
const VA3_FAMILY_VALUES: usize = 4_188 + 7_939 + 10_970 + 9_723;
const VA3_FAMILY: [&str; 4] = [
    "va3_facets_only_triangle_3",
    "va3_friction_prescribed_quadrangle_4",
    "va3_ig_tg_rules_zones",
    "va3_ig_tg_zone_btop",
];

#[test]
fn va3_oracle_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let expected: Vec<String> = VA3_FAMILY.iter().map(|s| (*s).to_owned()).collect();
    for case in family_cases("va3_oracle_cases", &expected) {
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        // D-050: generated with Eigen's cache sizes pinned
        assert_eq!(
            param(&f, "eigen_cache_sizes"),
            &serde_json::json!([16384, 524288, 524288]),
            "{case}: Eigen cache sizes of the oracle run"
        );
        let r = if case.starts_with("va3_facets_only") {
            replay_va3_facets_only(&f)
        } else if case.starts_with("va3_ig_tg") {
            let (r, n, _) = replay_va3_ig_tg(&f);
            assert!(n > 0, "{case}: the example inserts cohesive elements");
            // what the case exercises (oracle data, replayed bitwise above):
            // law of every cohesive element (tg_cohesive 2 at the btop–bbottom
            // interface, ig_cohesive 3 inside a volume) and the checkable
            // facets (cohesive_zones / addPhysicalVolume)
            let laws = i64s(&f, "final/material_index/_cohesive_2d_4");
            let tg = laws.iter().filter(|&&l| l == 2).count();
            let ig = laws.iter().filter(|&&l| l == 3).count();
            let checkable = i64s(&f, "init/check_facets/_segment_2")
                .iter()
                .filter(|&&c| c == 1)
                .count();
            let fmat = i64s(&f, "init/facet_material/_segment_2");
            eprintln!(
                "{case}: {checkable} checkable facets; facet laws tg {} ig {}; cohesive elements tg {tg} ig {ig}",
                fmat.iter().filter(|&&l| l == 2).count(),
                fmat.iter().filter(|&&l| l == 3).count()
            );
            assert_eq!(
                tg + ig,
                laws.len(),
                "{case}: every cohesive element has a rule law"
            );
            // the rules: the two btop–bbottom facets (element order
            // (bbottom, btop), the reversed key of the rule) get tg, all
            // others ig — but tg is also the default cohesive law here (the
            // first cohesive law), so these cases do not pin the reversed
            // lookup (v92_ig_tg_rules_* do); the zones:
            // every interior facet ([btop, bbottom]) or only btop's interior
            let zone_btop = case.ends_with("zone_btop");
            assert_eq!(
                (
                    fmat.iter().filter(|&&l| l == 2).count(),
                    fmat.iter().filter(|&&l| l == 3).count()
                ),
                (2, 26),
                "{case}: facet laws"
            );
            assert_eq!(
                checkable,
                if zone_btop { 9 } else { 20 },
                "{case}: checkable facets"
            );
            assert_eq!(
                laws.len(),
                if zone_btop { 9 } else { 18 },
                "{case}: insertions"
            );
            r
        } else {
            // UD-249 compat: upstream's residual sliding update, bitwise
            let (r, s) = replay_va3_friction(&f, true);
            eprintln!(
                "{case} (UD-249 compat): friction branch contact {} stick {} slip {} reverse {} sliding changes {}",
                s.contact, s.stick, s.slip_forward, s.reverse, s.sliding_changes
            );
            assert!(
                s.stick > 0 && s.slip_forward > 0 && s.reverse > 0 && s.sliding_changes > 0,
                "{case}: stick, slip and reverse sliding must all occur: {s:?}"
            );
            // the upstream run leaves the play operator (UD-249 chatter)
            let (wu, _) = friction_play_operator(&s.steps);
            assert!(wu > 0.5, "{case}: upstream vs play operator {wu:e} τ_max");
            // the corrected default: the play operator at every penetrating
            // step (closed-form bound), and differs from the oracle only from the
            // first reverse sliding on
            let (d, ds) = replay_va3_friction(&f, false);
            let (wd, checked) = friction_play_operator(&ds.steps);
            let first_reverse = s
                .steps
                .iter()
                .position(|st| {
                    st.friction_force[0] * st.opening[0] + st.friction_force[1] * st.opening[1]
                        < 0.0
                })
                .unwrap();
            let first_diff = ds.steps.iter().zip(&s.steps).position(|(a, b)| {
                a.residual_sliding.to_bits() != b.residual_sliding.to_bits()
                    || a.friction_force
                        .iter()
                        .zip(&b.friction_force)
                        .any(|(x, y)| x.to_bits() != y.to_bits())
            });
            eprintln!(
                "{case} (default, UD-249): play operator worst {wd:.3e} τ_max over {checked} penetrating steps (upstream {wu:.3e}); first difference from upstream at step {first_diff:?}, first reverse sliding upstream at step {first_reverse}; {} oracle quantities differ",
                d.errors.len()
            );
            assert!(wd <= 1e-13, "{case}: default vs play operator {wd:e} τ_max");
            assert!(checked >= 40, "{case}: penetrating steps checked {checked}");
            assert_eq!(
                first_diff,
                Some(first_reverse),
                "{case}: default vs upstream"
            );
            r
        };
        total += r.compared;
        eprintln!(
            "{case}: {} values compared, {} mismatching quantities",
            r.compared,
            r.errors.len()
        );
        for e in r.errors.iter().take(12) {
            eprintln!("    {e}");
        }
        if !r.errors.is_empty() {
            failures.push(case);
        }
    }
    assert!(failures.is_empty(), "{failures:?}");
    eprintln!("va3_oracle_cases: total {total} values compared");
    assert_family_total(
        "va3_oracle_cases",
        total,
        VA3_FAMILY_VALUES,
        VA3_FAMILY_VALUES,
        0,
    );
}

// ---------------------------------------------------------------------------
// The v92_* oracle cases (gap fixes)
// (oracle/probes/cohesive/cohesive_probe.cc, x86_64, compile-time pinned
// oracle, D-050). Replayed bitwise under the exact rule; each also asserts
// what it pins.
// ---------------------------------------------------------------------------

/// Replay of `v92_ig_tg_zones_update_after_insertion`
/// (UD-808): the upstream example up to the step of the first insertion,
/// with `update_automatic_insertion` before any insertion and after it.
/// `compat` (switch `zones_unnamed_neighbour_error`): every recorded
/// quantity bitwise, the second update fails with upstream's message and
/// leaves the flags as upstream's exception did. Default (UD-808 B): the
/// second update succeeds and recomputes exactly the flags the insertion
/// left (`after_insertion/`) — the result upstream would compute without the
/// exception. Returns the report and the error message of the compat run.
fn replay_v92_zone_update(f: &Fixture, compat: bool) -> (Report, Option<String>) {
    let mut r = Report::default();
    let c = akantu_cohesive::CohesiveUpstreamCompat {
        zones_unnamed_neighbour_error: compat,
        ..Default::default()
    };
    let (mut model, mesh, stable, dt) = ig_tg_model(f, c);
    r.bits("time_step", &[stable, dt], &f64s(f, "time_step"));
    compare_flags(f, &model, "init/", &mut r);
    // before any insertion the update succeeds in both modes
    model.update_automatic_insertion().unwrap();
    compare_flags(f, &model, "update_before/", &mut r);
    ig_tg_boundary(&mut model, &mesh);
    let max_steps = param(f, "max_steps").as_u64().unwrap() as usize;
    let (mut ins, mut ncoh, mut ek, mut ep) = (vec![], vec![], vec![], vec![]);
    let mut first = None;
    for s in 1..=max_steps {
        ig_tg_apply_velocity(&mut model, dt);
        let n = model.check_cohesive_stress().unwrap();
        ins.push(n as i64);
        ncoh.push(
            mesh.read()
                .unwrap()
                .nb_element(ElementType::Cohesive2d4, GhostType::NotGhost) as i64,
        );
        model.solve_step(None).unwrap();
        ek.push(model.energy("kinetic").unwrap());
        ep.push(model.energy("potential").unwrap());
        if n > 0 {
            first = Some(s);
            break;
        }
    }
    if first.map(|s| s as i64) != param(f, "first_insertion_step").as_i64() {
        r.errors.push(format!(
            "first insertion at step {first:?}, oracle {}",
            param(f, "first_insertion_step")
        ));
    }
    r.ints("steps/inserted", &ins, &i64s(f, "steps/inserted"));
    r.ints("steps/nb_cohesive", &ncoh, &i64s(f, "steps/nb_cohesive"));
    r.bits(
        "steps/energy/kinetic",
        &ek,
        &f64s(f, "steps/energy/kinetic"),
    );
    r.bits(
        "steps/energy/potential",
        &ep,
        &f64s(f, "steps/energy/potential"),
    );
    compare_nodal_state(f, &model, "after_insertion/", &mut r);
    compare_flags(f, &model, "after_insertion/", &mut r);
    compare_topology(f, &model, &mut r);
    // upstream: the cohesive type has no physical_names array
    assert_eq!(
        param(f, "physical_names_has_cohesive_type").as_bool(),
        Some(false)
    );
    assert!(
        !mesh
            .read()
            .unwrap()
            .data()
            .strings("physical_names")
            .unwrap()
            .exists(ElementType::Cohesive2d4, GhostType::NotGhost),
        "the port's physical_names has no cohesive block either"
    );
    let res = model.update_automatic_insertion();
    let mut message = None;
    if compat {
        match res {
            Err(akantu_core::Error::Mesh(msg)) => {
                if Some(msg.as_str()) != param(f, "upstream_error").as_str() {
                    r.errors.push(format!(
                        "UD-808 compat message {msg:?} vs oracle {}",
                        param(f, "upstream_error")
                    ));
                }
                message = Some(msg);
            }
            other => r.errors.push(format!(
                "UD-808 compat: update after the insertion returned {other:?}"
            )),
        }
        compare_flags(f, &model, "after_error/", &mut r);
        assert_all_compared(f, &r.names, &[]);
    } else {
        res.unwrap();
        // the recomputed flags are those the insertion left
        let mut d = Report::default();
        compare_flags(f, &model, "after_insertion/", &mut d);
        for e in d.errors {
            r.errors.push(format!("default update: {e}"));
        }
    }
    (r, message)
}

/// `v92_oracle_cases` values: rules both keys 10,970 + rules reversed key
/// 10,970 + zone update 2,578 + implicit uncoupled 2,545.
const V92_FAMILY_VALUES: usize = 10_970 + 10_970 + 2_578 + 2_545;
const V92_FAMILY: [&str; 4] = [
    "v92_ig_tg_rules_both_keys",
    "v92_ig_tg_rules_reversed_key",
    "v92_ig_tg_zones_update_after_insertion",
    "v92_implicit_uncoupled_prestressed_reversal",
];

#[test]
fn v92_oracle_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let expected: Vec<String> = V92_FAMILY.iter().map(|s| (*s).to_owned()).collect();
    for case in family_cases("v92_oracle_cases", &expected) {
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        // D-050: generated with Eigen's cache sizes pinned
        assert_eq!(
            param(&f, "eigen_cache_sizes"),
            &serde_json::json!([16384, 524288, 524288]),
            "{case}: Eigen cache sizes of the oracle run"
        );
        let r = if case == "v92_ig_tg_zones_update_after_insertion" {
            let (r, msg) = replay_v92_zone_update(&f, true);
            eprintln!("{case} (UD-808 compat): upstream error {msg:?}");
            let (d, _) = replay_v92_zone_update(&f, false);
            for e in d.errors.iter().take(12) {
                eprintln!("    default: {e}");
            }
            assert!(
                d.errors.is_empty(),
                "{case}: default run (UD-808 corrected behaviour)"
            );
            r
        } else if case.starts_with("v92_ig_tg_rules") {
            let (r, n, neighbours) = replay_va3_ig_tg(&f);
            assert!(n > 0, "{case}: the example inserts cohesive elements");
            // material order btop, bbottom, ig_cohesive, tg_cohesive: the
            // default cohesive law (the first cohesive one) is ig (2)
            assert_eq!(param(&f, "ig_first").as_bool(), Some(true));
            let (ig, tg) = (2, 3);
            let fmat = i64s(&f, "init/facet_material/_segment_2");
            let interface: Vec<usize> = (0..neighbours.len())
                .filter(|&k| neighbours[k].0 != neighbours[k].1)
                .collect();
            // the interface facets are (bbottom, btop) in element order:
            // the rule key (btop, bbottom) is their reversed key
            assert_eq!(interface.len(), 2, "{case}: interface facets");
            for &k in &interface {
                assert_eq!(
                    neighbours[k],
                    ("bbottom".to_owned(), "btop".to_owned()),
                    "{case}: facet {k}"
                );
                // reversed_key: found only by the second lookup (tg), not the
                // default (ig); both_keys: the direct key (bbottom, btop) → tg
                // wins over the reversed (btop, bbottom) → ig
                assert_eq!(fmat[k], tg, "{case}: interface facet {k} law");
            }
            for k in (0..fmat.len()).filter(|k| !interface.contains(k)) {
                assert_eq!(fmat[k], ig, "{case}: facet {k} law");
            }
            let laws = i64s(&f, "final/material_index/_cohesive_2d_4");
            eprintln!(
                "{case}: cohesive elements tg {} ig {}",
                laws.iter().filter(|&&l| l == tg).count(),
                laws.iter().filter(|&&l| l == ig).count()
            );
            r
        } else {
            let c = replay_v57_adversarial(&f, Switches::UPSTREAM);
            eprintln!(
                "{case} (upstream switch set): {} values compared, {} mismatching; {} attempts, {} iterations, contact at {} converged steps, non-converged {:?}",
                c.report.compared,
                c.report.errors.len(),
                c.iterations.len(),
                c.iterations.iter().sum::<i64>(),
                c.contact_steps.len(),
                c.not_converged
            );
            assert_eq!(
                param(&f, "prestress_inserted").as_i64(),
                Some(1),
                "{case}: one cohesive element inserted by the stress check"
            );
            assert!(
                !c.contact_steps.is_empty(),
                "{case}: the contact branch is reached"
            );
            let d = replay_v57_adversarial(&f, Switches::DEFAULT);
            eprintln!(
                "{case} (default): {} attempts, {} iterations, contact at {} converged steps, non-converged {:?}",
                d.iterations.len(),
                d.iterations.iter().sum::<i64>(),
                d.contact_steps.len(),
                d.not_converged
            );
            assert_eq!(d.failed_step, -1, "{case}: the default run converges");
            // the case pins upstream's uncoupled tangent: with every
            // upstream switch but UD-244 (for this law
            // `upstream_tangent_contact` is UD-244 alone) the final K
            // differs from the oracle's
            let u = replay_v57_adversarial(
                &f,
                Switches {
                    upstream_tangent_contact: false,
                    ..Switches::UPSTREAM
                },
            );
            let oracle_k = f64s(&f, "K/values");
            assert_eq!(u.k_values.len(), oracle_k.len(), "{case}: K storage");
            let differing = u
                .k_values
                .iter()
                .zip(&oracle_k)
                .filter(|(a, b)| a.to_bits() != b.to_bits())
                .count();
            eprintln!(
                "{case}: without the UD-244 switch {differing}/{} final K values differ from the oracle",
                oracle_k.len()
            );
            assert!(differing > 0, "{case}: the case must discriminate UD-244");
            c.report
        };
        total += r.compared;
        eprintln!(
            "{case}: {} values compared, {} mismatching quantities",
            r.compared,
            r.errors.len()
        );
        for e in r.errors.iter().take(12) {
            eprintln!("    {e}");
        }
        if !r.errors.is_empty() {
            failures.push(case);
        }
    }
    assert!(failures.is_empty(), "{failures:?}");
    eprintln!("v92_oracle_cases: total {total} values compared");
    assert_family_total(
        "v92_oracle_cases",
        total,
        V92_FAMILY_VALUES,
        V92_FAMILY_VALUES,
        0,
    );
}

// ---------------------------------------------------------------------------
// The cmf_* oracle cases (friction fixes)
// (oracle/probes/cohesive/cohesive_probe.cc, x86_64, compile-time pinned
// oracle, D-050), replayed bitwise in compat mode; each also asserts what it
// pins and checks the corrected default.
// ---------------------------------------------------------------------------

/// `cmf_oracle_cases` values: explicit 3-D friction 25,246 + implicit
/// friction 2,151.
const CMF_FAMILY_VALUES: usize = CMF_EXPLICIT_VALUES + CMF_IMPLICIT_VALUES;
const CMF_EXPLICIT_VALUES: usize = 25_246;
const CMF_IMPLICIT_VALUES: usize = 2_151;

/// The friction oracle cases.
///
/// * `cmf_friction_prescribed_tetrahedron_4` (explicit, 3-D, prescribed
///   rigid motion with a change of the sliding direction): bitwise under
///   the **UD-249** switch; the upstream run leaves the play operator; the
///   corrected default follows it at every penetrating step and
///   differs from upstream exactly from the first reverse sliding on.
/// * `cmf_implicit_friction_prestressed_sliding` (implicit static, the
///   probe activates the `delta max` history, UD-028 A): bitwise under the
///   upstream switch set (UD-247 and UD-249 included); the case discriminates
///   both switches (without either, the replay leaves the oracle); the
///   corrected default converges at every step, in fewer Newton iterations
///   (the exact tangent), through contact and reverse sliding.
#[test]
fn cmf_oracle_cases() {
    let _g = common::lock();
    let mut failures = Vec::new();
    let mut total = 0;
    let expected: Vec<String> = CMF_FAMILY.iter().map(|s| (*s).to_owned()).collect();
    for case in family_cases("cmf_oracle_cases", &expected) {
        let f = open(&case).unwrap();
        assert_upstream_error_status(&case, &f);
        // D-050: generated with Eigen's cache sizes pinned
        assert_eq!(
            param(&f, "eigen_cache_sizes"),
            &serde_json::json!([16384, 524288, 524288]),
            "{case}: Eigen cache sizes of the oracle run"
        );
        let r = if case == "cmf_friction_prescribed_tetrahedron_4" {
            let path = cmf_friction_path();
            let (r, s) = replay_prescribed_friction(&f, true, 3, ElementType::Cohesive3d6, &path);
            eprintln!(
                "{case} (UD-249 compat): friction branch contact {} stick {} slip {} reverse {} sliding changes {}",
                s.contact, s.stick, s.slip_forward, s.reverse, s.sliding_changes
            );
            assert!(
                s.stick > 0 && s.slip_forward > 0 && s.reverse > 0 && s.sliding_changes > 0,
                "{case}: stick, slip and reverse sliding must all occur: {s:?}"
            );
            let (wu, _) = friction_play_operator(&s.steps);
            assert!(wu > 0.5, "{case}: upstream vs play operator {wu:e} τ_max");
            let (d, ds) = replay_prescribed_friction(&f, false, 3, ElementType::Cohesive3d6, &path);
            let (wd, checked) = friction_play_operator(&ds.steps);
            let first_reverse = s
                .steps
                .iter()
                .position(|st| {
                    st.friction_force
                        .iter()
                        .zip(&st.opening)
                        .map(|(a, b)| a * b)
                        .sum::<Real>()
                        < 0.0
                })
                .unwrap();
            let first_diff = ds.steps.iter().zip(&s.steps).position(|(a, b)| {
                a.residual_sliding.to_bits() != b.residual_sliding.to_bits()
                    || a.friction_force
                        .iter()
                        .zip(&b.friction_force)
                        .any(|(x, y)| x.to_bits() != y.to_bits())
            });
            eprintln!(
                "{case} (default, UD-249): play operator worst {wd:.3e} τ_max over {checked} penetrating steps (upstream {wu:.3e}); first difference from upstream at step {first_diff:?}, first reverse sliding upstream at step {first_reverse}; {} oracle quantities differ",
                d.errors.len()
            );
            assert!(wd <= 1e-13, "{case}: default vs play operator {wd:e} τ_max");
            assert!(checked >= 60, "{case}: penetrating steps checked {checked}");
            assert_eq!(
                first_diff,
                Some(first_reverse),
                "{case}: default vs upstream"
            );
            r
        } else {
            assert_eq!(
                param(&f, "probe_delta_max_history").as_bool(),
                Some(true),
                "{case}: the probe activates the delta max history (UD-028)"
            );
            let c = replay_v57_adversarial(&f, Switches::UPSTREAM);
            let its: i64 = c.iterations.iter().sum();
            eprintln!(
                "{case} (upstream switch set, delta max history): {} values compared, {} mismatching; {} attempts, {its} iterations, contact at {} converged steps, reverse sliding at {}, non-converged {:?}",
                c.report.compared,
                c.report.errors.len(),
                c.iterations.len(),
                c.contact_steps.len(),
                c.reverse_steps.len(),
                c.not_converged
            );
            assert_eq!(
                c.failed_step, -1,
                "{case}: upstream converges at every step"
            );
            assert!(
                c.contact_steps.len() >= 40 && c.reverse_steps.len() >= 10,
                "{case}: contact and reverse sliding are reached"
            );
            // the case discriminates both friction switches: without either,
            // the replay leaves the oracle (iterations or final K)
            let oracle_its = i64s(&f, "attempts/nb_iterations");
            let oracle_k = f64s(&f, "K/values");
            for (what, sw) in [
                (
                    "UD-247",
                    Switches {
                        friction_implicit: false,
                        ..Switches::UPSTREAM
                    },
                ),
                (
                    "UD-249",
                    Switches {
                        friction_abs: false,
                        ..Switches::UPSTREAM
                    },
                ),
            ] {
                let u = replay_v57_adversarial(&f, sw);
                let k_diff = u.k_values.len() != oracle_k.len()
                    || u.k_values
                        .iter()
                        .zip(&oracle_k)
                        .any(|(a, b)| a.to_bits() != b.to_bits());
                eprintln!(
                    "{case}: without the {what} switch: {} iterations (oracle {}), final K differs {k_diff}",
                    u.iterations.iter().sum::<i64>(),
                    oracle_its.iter().sum::<i64>()
                );
                assert!(
                    k_diff || u.iterations != oracle_its,
                    "{case}: the case must discriminate {what}"
                );
            }
            let d = replay_v57_adversarial(&f, Switches::DEFAULT);
            let dits: i64 = d.iterations.iter().sum();
            eprintln!(
                "{case} (default): {} attempts, {dits} iterations (max {}), contact at {} converged steps, reverse sliding at {}, non-converged {:?}",
                d.iterations.len(),
                d.iterations.iter().max().copied().unwrap_or(0),
                d.contact_steps.len(),
                d.reverse_steps.len(),
                d.not_converged
            );
            assert_eq!(d.failed_step, -1, "{case}: the default run converges");
            assert!(
                d.contact_steps.len() >= 40 && d.reverse_steps.len() >= 10,
                "{case}: default contact and reverse sliding"
            );
            assert!(
                dits < its,
                "{case}: the exact tangent needs fewer iterations"
            );
            c.report
        };
        total += r.compared;
        eprintln!(
            "{case}: {} values compared, {} mismatching quantities",
            r.compared,
            r.errors.len()
        );
        for e in r.errors.iter().take(12) {
            eprintln!("    {e}");
        }
        if !r.errors.is_empty() {
            failures.push(case);
        }
    }
    assert!(failures.is_empty(), "{failures:?}");
    eprintln!("cmf_oracle_cases: total {total} values compared");
    assert_family_total(
        "cmf_oracle_cases",
        total,
        CMF_FAMILY_VALUES,
        CMF_FAMILY_VALUES,
        0,
    );
}
